#include <stdio.h>
#include <string.h>

enum { sq_am_inkling_H = 2304, sq_am_inkling_Q = 3072, sq_am_inkling_KV = 1024, sq_am_inkling_R = 384, sq_am_inkling_E = 128, sq_am_inkling_I = 1152, sq_am_inkling_V = 201024, sq_am_inkling_M = 9216 };

struct sq_inkling_checkpoint {
    sq_options allocator;
    sq_safetensors *files[2];
    const sq_tensor_info *bound[2048];
    uint32_t sources[2048];
    size_t count;
};

static sq_status sq_am_inkling_spec(sq_spec_fn visit, void *context, uint32_t source, const char *prefix,
                      const char *suffix, sq_dtype dtype, uint64_t a, uint64_t b, uint64_t c) {
    sq_inkling_spec s = {0};
    int n = snprintf(s.name, sizeof s.name, "%s%s", prefix, suffix);
    if (n < 0 || (size_t)n >= sizeof s.name)
        return sq_error(SQ_LIMIT, "internal tensor name limit");
    s.source = source;
    s.dtype = dtype;
    s.rank = c ? 3 : b ? 2 : 1;
    s.shape[0] = a;
    s.shape[1] = b;
    s.shape[2] = c;
    return visit(context, &s);
}

#define S(src, pre, suf, type, a, b, c)                                                            \
    do {                                                                                           \
        sq_status st = sq_am_inkling_spec(visit, context, src, pre, suf, type, a, b, c);                         \
        if (st != SQ_OK)                                                                           \
            return st;                                                                             \
    } while (0)

sq_status sq_inkling_visit_specs(uint32_t include_mtp, sq_spec_fn visit, void *context) {
    if (!visit || include_mtp > 1)
        return sq_error(SQ_INVALID_ARGUMENT, "invalid schema visitor");
    const char *base = "model.llm.";
    S(0, base, "embed.weight", SQ_BF16, sq_am_inkling_V, sq_am_inkling_H, 0);
    S(0, base, "embed_norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
    S(0, base, "norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
    S(0, base, "unembed.weight", SQ_BF16, sq_am_inkling_V, sq_am_inkling_H, 0);
    char p[96];
    for (unsigned l = 0; l < 23; l++) {
        (void)snprintf(p, sizeof p, "model.llm.attn_res.attn_queries.%u", l);
        bool global = (l + 2) % 6 == 0;
        S(0, p, "", SQ_F32, global ? 3 : sq_am_inkling_H, global ? sq_am_inkling_H : 0, 0);
    }
    for (unsigned l = 0; l < 24; l++) {
        (void)snprintf(p, sizeof p, "model.llm.attn_res.mlp_queries.%u", l);
        S(0, p, "", SQ_F32, sq_am_inkling_H, 0, 0);
    }
    S(0, base, "attn_res.output_query", SQ_F32, sq_am_inkling_H, 0, 0);
    S(0, base, "middle_cycle_cross_pass_queries", SQ_F32, 24, sq_am_inkling_H, 0);
    S(0, base, "middle_cycle_cross_pass_kv_queries", SQ_F32, 24, sq_am_inkling_H, 0);
    for (unsigned l = 0; l < 24; l++) {
        (void)snprintf(p, sizeof p, "model.llm.layers.%u.", l);
        bool global = (l + 1) % 6 == 0;
        if (global) {
            S(0, p, "q_input_norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
            S(0, p, "k_input_norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
            S(0, p, "v_input_norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
        } else
            S(0, p, "attn_norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
        S(0, p, "mlp_norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
        S(0, p, "attn.wq_du.weight", SQ_BF16, sq_am_inkling_Q, sq_am_inkling_H, 0);
        S(0, p, "attn.wr_du.weight", SQ_BF16, sq_am_inkling_R, sq_am_inkling_H, 0);
        S(0, p, "attn.gate_attn.weight", SQ_BF16, sq_am_inkling_Q, sq_am_inkling_H, 0);
        S(0, p, "attn.attn_sink_proj.weight", SQ_BF16, 24, sq_am_inkling_H, 0);
        S(0, p, "attn.wk_dv.weight", SQ_BF16, sq_am_inkling_KV, sq_am_inkling_H, 0);
        S(0, p, "attn.wv_dv.weight", SQ_BF16, sq_am_inkling_KV, sq_am_inkling_H, 0);
        S(0, p, "attn.wo_ud.weight", SQ_BF16, sq_am_inkling_H, sq_am_inkling_Q, 0);
        if (global) {
            S(0, p, "attn.k_sconv.static_w", SQ_BF16, 4, sq_am_inkling_KV, 0);
            S(0, p, "attn.v_sconv.static_w", SQ_BF16, 4, sq_am_inkling_KV, 0);
            S(0, p, "attn.k_sconv.weight_proj", SQ_BF16, 32, sq_am_inkling_H, 0);
            S(0, p, "attn.v_sconv.weight_proj", SQ_BF16, 32, sq_am_inkling_H, 0);
        } else {
            S(0, p, "attn.k_sconv.weight", SQ_BF16, sq_am_inkling_KV, 1, 4);
            S(0, p, "attn.v_sconv.weight", SQ_BF16, sq_am_inkling_KV, 1, 4);
        }
        S(0, p, "attn_sconv.weight", SQ_BF16, sq_am_inkling_H, 1, 4);
        S(0, p, "mlp_sconv.weight", SQ_BF16, sq_am_inkling_H, 1, 4);
        S(0, p, "attn.q_l2_clip.scale", SQ_BF16, 24, 128, 0);
        S(0, p, "attn.rel_l2_clip.scale", SQ_BF16, 24, 16, 0);
        S(0, p, "attn.rel_logits_proj.proj", SQ_BF16, 16, 1024, 0);
        if (l >= 6 && l < 18) {
            const char *stems[] = {"attn", "k", "v", "mlp"};
            char cpre[112];
            for (size_t j = 0; j < 4; j++) {
                (void)snprintf(cpre, sizeof cpre, "%scontrollers.%s.", p, stems[j]);
                S(0, cpre, "down_weight", SQ_BF16, 64, 2 * sq_am_inkling_H, 0);
                S(0, cpre, "forget_weight", SQ_BF16, sq_am_inkling_H, 64, 0);
                S(0, cpre, "gain_weight", SQ_BF16, sq_am_inkling_H, 64, 0);
            }
        }
        S(0, p, "mlp.gate.weight", SQ_BF16, sq_am_inkling_E, sq_am_inkling_H, 0);
        S(0, p, "mlp.gate.bias", SQ_F32, sq_am_inkling_E, 0, 0);
        const char *banks[] = {"w13", "w2"};
        for (size_t j = 0; j < 2; j++) {
            unsigned rows = j ? sq_am_inkling_H : 2 * sq_am_inkling_I, cols = j ? sq_am_inkling_I : sq_am_inkling_H;
            char n[128];
            (void)snprintf(n, sizeof n, "%smlp.experts.%s_weight", p, banks[j]);
            S(0, n, "", l < 20 ? SQ_U8 : SQ_F8_E4M3, sq_am_inkling_E, rows, l < 20 ? cols / 2 : cols);
            S(0, n, "_scale", l < 20 ? SQ_F8_E4M3 : SQ_U8, sq_am_inkling_E, rows, l < 20 ? cols / 16 : cols / 32);
            if (l < 20) {
                S(0, n, "_amax", SQ_F32, sq_am_inkling_E, 0, 0);
                S(0, n, "_outer_scale_denominator", SQ_F32, 1, 0, 0);
            }
        }
    }
    if (!include_mtp)
        return SQ_OK;
    S(1, "", "fuse_weight", SQ_BF16, 4, 4, 0);
    S(1, "", "mask_embed", SQ_BF16, sq_am_inkling_H, 0, 0);
    S(1, "", "norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
    S(1, "", "markov_head.dflare_norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
    S(1, "", "markov_head.markov_w1.weight", SQ_BF16, sq_am_inkling_V, 256, 0);
    S(1, "", "markov_head.rnn_proj.bias", SQ_BF16, 768, 0, 0);
    S(1, "", "markov_head.rnn_proj.weight", SQ_BF16, 768, 5120, 0);
    S(1, "", "markov_head.hidden_out.weight", SQ_BF16, sq_am_inkling_H, 256, 0);
    S(1, "", "markov_head.hidden_out.bias", SQ_BF16, sq_am_inkling_H, 0, 0);
    for (unsigned l = 0; l < 3; l++) {
        (void)snprintf(p, sizeof p, "layers.%u.", l);
        S(1, p, "input_layernorm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
        S(1, p, "post_attention_layernorm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
        S(1, p, "dflare_norm.weight", SQ_BF16, sq_am_inkling_H, 0, 0);
        S(1, p, "self_attn.q_norm.weight", SQ_BF16, 128, 0, 0);
        S(1, p, "self_attn.k_norm.weight", SQ_BF16, 128, 0, 0);
        S(1, p, "self_attn.k_norm_ctx.weight", SQ_BF16, 128, 0, 0);
        S(1, p, "self_attn.q_proj.weight", SQ_BF16, sq_am_inkling_Q, sq_am_inkling_H, 0);
        S(1, p, "self_attn.k_proj.weight", SQ_BF16, sq_am_inkling_KV, sq_am_inkling_H, 0);
        S(1, p, "self_attn.v_proj.weight", SQ_BF16, sq_am_inkling_KV, sq_am_inkling_H, 0);
        S(1, p, "self_attn.o_proj.weight", SQ_BF16, sq_am_inkling_H, sq_am_inkling_Q, 0);
        S(1, p, "mlp.gate_proj.weight", SQ_BF16, sq_am_inkling_M, sq_am_inkling_H, 0);
        S(1, p, "mlp.up_proj.weight", SQ_BF16, sq_am_inkling_M, sq_am_inkling_H, 0);
        S(1, p, "mlp.down_proj.weight", SQ_BF16, sq_am_inkling_H, sq_am_inkling_M, 0);
        S(1, p, "self_attn.k_proj_ctx.weight", SQ_BF16, sq_am_inkling_KV, sq_am_inkling_H, 0);
        S(1, p, "self_attn.v_proj_ctx.weight", SQ_BF16, sq_am_inkling_KV, sq_am_inkling_H, 0);
    }
    return SQ_OK;
}

#undef S

sq_status sq_inkling_check_descriptor(const sq_tensor_info *t, const sq_inkling_spec *s) {
    if (!t || !s || !s->rank || s->rank > 3)
        return sq_error(SQ_INVALID_ARGUMENT, "missing descriptor/schema");
    if (strcmp(t->name, s->name) || t->dtype != s->dtype || t->rank != s->rank)
        return sq_error(SQ_FORMAT, "Inkling tensor name/dtype/rank mismatch");
    for (uint32_t i = 0; i < s->rank; i++)
        if (t->shape[i] != s->shape[i])
            return sq_error(SQ_FORMAT, "Inkling tensor shape mismatch");
    return SQ_OK;
}

static sq_status sq_am_inkling_bind(void *context, const sq_inkling_spec *s) {
    sq_inkling_checkpoint *c = context;
    const sq_tensor_info *t = NULL;
    sq_status status = sq_safetensors_find(c->files[s->source], s->name, strlen(s->name), &t);
    if (status == SQ_OK)
        status = sq_inkling_check_descriptor(t, s);
    if (status != SQ_OK) {
        char message[256];
        (void)snprintf(message, sizeof message, "invalid/missing required tensor: %s", s->name);
        return sq_error(SQ_FORMAT, message);
    }
    if (c->count == 2048)
        return sq_error(SQ_LIMIT, "bound tensor limit");
    c->bound[c->count] = t;
    c->sources[c->count++] = s->source;
    return SQ_OK;
}

void sq_inkling_checkpoint_close(sq_inkling_checkpoint *c) {
    if (!c)
        return;
    sq_options a = c->allocator;
    sq_safetensors_close(c->files[1]);
    sq_safetensors_close(c->files[0]);
    a.release(a.context, c);
}

sq_status sq_inkling_checkpoint_open(const char *main_path, const char *mtp_path,
                                     const sq_options *options, sq_inkling_checkpoint **out) {
    if (out)
        *out = NULL;
    if (!main_path || !main_path[0] || !out)
        return sq_error(SQ_INVALID_ARGUMENT, "missing checkpoint path/output");
    sq_options a;
    sq_status status = sq_options_resolve(options, &a);
    if (status != SQ_OK)
        return status;
    sq_inkling_checkpoint *c = a.allocate(a.context, sizeof *c);
    if (!c)
        return sq_error(SQ_OUT_OF_MEMORY, "allocate checkpoint binding");
    memset(c, 0, sizeof *c);
    c->allocator = a;
    status = sq_safetensors_open(main_path, &a, &c->files[0]);
    if (status != SQ_OK)
        goto fail;
    if (mtp_path) {
        status = sq_safetensors_open(mtp_path, &a, &c->files[1]);
        if (status != SQ_OK)
            goto fail;
    }
    status = sq_inkling_visit_specs(mtp_path != NULL, sq_am_inkling_bind, c);
    if (status != SQ_OK)
        goto fail;
    size_t counts[2] = {0};
    for (size_t i = 0; i < c->count; i++)
        counts[c->sources[i]]++;
    for (size_t source = 0; source < 2; source++) {
        for (size_t i = 0; i < sq_safetensors_count(c->files[source]); i++) {
            const sq_tensor_info *t = NULL;
            (void)sq_safetensors_at(c->files[source], i, &t);
            if (source == 0 && !strncmp(t->name, "model.visual.", 13))
                continue;
            if (counts[source] == 0) {
                status = sq_error(SQ_FORMAT, "unexpected checkpoint tensors");
                goto fail;
            }
            counts[source]--;
        }
        if (counts[source]) {
            status = sq_error(SQ_FORMAT, "checkpoint role coverage mismatch");
            goto fail;
        }
    }
    *out = c;
    return sq_error(SQ_OK, "");
fail:
    sq_inkling_checkpoint_close(c);
    return status;
}

size_t sq_inkling_checkpoint_count(const sq_inkling_checkpoint *c) {
    return c ? c->count : 0;
}

sq_status sq_inkling_checkpoint_at(const sq_inkling_checkpoint *c, size_t index, uint32_t *source,
                                   const sq_tensor_info **out) {
    if (source)
        *source = 0;
    if (out)
        *out = NULL;
    if (!c || !source || !out)
        return sq_error(SQ_INVALID_ARGUMENT, "missing binding outputs");
    if (index >= c->count)
        return sq_error(SQ_NOT_FOUND, "bound tensor not found");
    *source = c->sources[index];
    *out = c->bound[index];
    return sq_error(SQ_OK, "");
}

sq_status sq_inkling_checkpoint_data(const sq_inkling_checkpoint *c, size_t index, const void **out,
                                     size_t *bytes) {
    if (out)
        *out = NULL;
    if (bytes)
        *bytes = 0;
    if (!c || !out || !bytes)
        return sq_error(SQ_INVALID_ARGUMENT, "missing bound data output");
    if (index >= c->count)
        return sq_error(SQ_NOT_FOUND, "bound tensor not found");
    const sq_tensor_info *bound = c->bound[index];
    sq_safetensors *file = c->files[c->sources[index]];
    for (size_t i = 0; i < sq_safetensors_count(file); i++) {
        const sq_tensor_info *t = NULL;
        (void)sq_safetensors_at(file, i, &t);
        if (t == bound)
            return sq_safetensors_data(file, i, out, bytes);
    }
    return sq_error(SQ_FORMAT, "invalid binding");
}

sq_status sq_inkling_lookup(const sq_inkling_checkpoint *c, uint32_t source, const char *name,
                            const void **out, size_t *bytes) {
    if (out)
        *out = NULL;
    if (bytes)
        *bytes = 0;
    if (!c || source > 1 || !name || !out || !bytes)
        return sq_error(SQ_INVALID_ARGUMENT, "invalid weight source");
    return sq_safetensors_named_data(c->files[source], name, out, bytes);
}

