/* Module: src/sampling.c */
/* SPDX-License-Identifier: Apache-2.0; Copyright (c) 2026 Artalis */

#include <math.h>
#include <string.h>

sq_status sq_decode_resolve(const sq_decode_options *input, sq_decode_options *out) {
    const sq_decode_options defaults = SQ_DECODE_OPTIONS_INIT;
    *out = defaults;
    if (input) {
        size_t size;
        uint32_t version;
        memcpy(&size, input, sizeof size);
        const size_t legacy = offsetof(sq_decode_options, adaptive);
        const size_t adaptive = offsetof(sq_decode_options, system_prefix_tokens);
        if (size != legacy && size != adaptive && size < sizeof *input)
            return sq_error(SQ_INVALID_ARGUMENT, "unsupported decode options size");
        memcpy(&version, (const unsigned char *)input + offsetof(sq_decode_options, api_version),
               sizeof version);
        if (version != SQ_API_VERSION)
            return sq_error(SQ_INVALID_ARGUMENT, "unsupported decode options version");
        memcpy(out, input, size < sizeof *input ? size : sizeof *input);
    }
    if (!isfinite(out->temperature) || out->temperature < 0 || !isfinite(out->top_p) ||
        out->top_p <= 0 || out->top_p > 1 || out->top_k < 0 || out->top_k > 200058 ||
        out->draft_tokens > 7 || out->reserved || out->adaptive > 1 || out->prompt_lookup > 1 ||
        out->adaptive_reserved || out->prefix_reserved || !isfinite(out->spec_threshold) ||
        out->spec_threshold <= 0 || out->spec_threshold > 1 ||
        (out->adaptive && out->draft_tokens != 7) || (out->prompt_lookup && !out->adaptive))
        return sq_error(SQ_INVALID_ARGUMENT, "invalid temperature/top-p/top-k/draft options");
    return SQ_OK;
}


/* Module: src/lookup.c */
/* SPDX-License-Identifier: Apache-2.0
 * Copyright (c) 2026 tensorfish; Copyright (c) 2026 Artalis
 * Pinned PromptLookupIndex translation: wrapping unsigned hash, 16-token
 * confirmation, two candidates and generation-stamped 8192-token history. */

#include <string.h>

static uint64_t sq_am_lookup_hash4(int32_t a, int32_t b, int32_t c, int32_t d) {
    uint64_t h = (uint64_t)(int64_t)a * UINT64_C(0x9e3779b97f4a7c15);
    h = (h ^ (uint64_t)(int64_t)b) * UINT64_C(0xbf58476d1ce4e5b9);
    h = (h ^ (uint64_t)(int64_t)c) * UINT64_C(0x94d049bb133111eb);
    h = (h ^ (uint64_t)(int64_t)d) * UINT64_C(0x9e3779b97f4a7c15);
    return h ^ (h >> 31);
}

static int32_t sq_am_lookup_at(const sq_lookup *s, uint32_t i) {
    return s->history[i & 8191];
}

static uint64_t sq_am_lookup_suffix(const sq_lookup *s) {
    uint32_t n = s->count;
    return sq_am_lookup_hash4(sq_am_lookup_at(s, n - 4), sq_am_lookup_at(s, n - 3), sq_am_lookup_at(s, n - 2), sq_am_lookup_at(s, n - 1));
}

void sq_lookup_reset(sq_lookup *s) {
    s->count = 0;
    s->generation = (uint16_t)(s->generation + 1u);
    if (!s->generation) {
        memset(s->stamp, 0, sizeof s->stamp);
        s->generation = 1;
    }
}

void sq_lookup_push(sq_lookup *s, int32_t token) {
    uint32_t i = s->count;
    s->history[i & 8191] = token;
    s->count = i + 1;
    if (s->count < 4)
        return;
    uint64_t h = sq_am_lookup_suffix(s);
    size_t slot = (size_t)(h & 16383);
    if (s->stamp[slot] == s->generation && s->hash[slot] == h) {
        s->older[slot] = s->newest[slot];
        s->newest[slot] = s->count;
    } else {
        s->hash[slot] = h;
        s->newest[slot] = s->count;
        s->older[slot] = 0;
        s->stamp[slot] = s->generation;
    }
}

bool sq_lookup_match(const sq_lookup *s, int32_t out[7]) {
    uint32_t n = s->count;
    if (n < 24)
        return false;
    uint64_t h = sq_am_lookup_suffix(s);
    size_t slot = (size_t)(h & 16383);
    if (s->stamp[slot] != s->generation || s->hash[slot] != h)
        return false;
    uint32_t candidate = s->newest[slot] == n ? s->older[slot] : s->newest[slot];
    if (candidate < 16 || candidate >= n || n - candidate <= 7)
        return false;
    uint32_t low = n > 8192 ? n - 8192 : 0;
    if (candidate - 16 < low)
        return false;
    for (uint32_t k = 1; k <= 16; k++)
        if (sq_am_lookup_at(s, candidate - k) != sq_am_lookup_at(s, n - k))
            return false;
    for (uint32_t j = 0; j < 7; j++)
        out[j] = sq_am_lookup_at(s, candidate + j);
    return true;
}


/* Module: src/chat.c */
/* SPDX-License-Identifier: Apache-2.0
 * Copyright (c) 2026 tensorfish; Copyright (c) 2026 Artalis
 * Text subset of pinned server.zig's segmented chat encoder. */


#include <string.h>

static bool sq_am_chat_utf8(const char *p, size_t n) {
    size_t at = 0;
    uint32_t cp;
    while (at < n)
        if (!sq_utf8_next((const unsigned char *)p, n, &at, &cp))
            return false;
    return true;
}

static bool sq_am_chat_marker(const sq_tokenizer *t, const char *p) {
    int32_t id = sq_special_lookup(t, p, strlen(p));
    return id >= 0 && t->entries[id].special;
}

typedef struct {
    const sq_tokenizer *t;
    sq_tokenizer_scratch *scratch;
    int32_t *out;
    size_t capacity, count;
    sq_status status;
} encoder;

static void sq_am_chat_append(encoder *e, const char *p, size_t n, uint32_t special) {
    if (e->status != SQ_OK || !n)
        return;
    size_t count = 0;
    sq_status rc =
        sq_tokenizer_encode(e->t, p, n, special, e->scratch, e->out ? e->out + e->count : NULL,
                            e->out ? e->capacity - e->count : 0, &count);
    if (rc != SQ_OK && !(rc == SQ_BUFFER_TOO_SMALL && !e->out)) {
        e->status = rc;
        return;
    }
    if (!sq_size_add(e->count, count, &e->count))
        e->status = SQ_LIMIT;
}

static void sq_am_chat_tag(encoder *e, const char *p) {
    sq_am_chat_append(e, p, strlen(p), 1);
}

static void sq_am_chat_effort(encoder *e, uint32_t value) {
    static const char *levels[] = {"0", "0.1", "0.2", "0.7", "0.9", "0.99"};
    sq_am_chat_tag(e, "<|message_system|><|content_text|>Thinking effort level: ");
    sq_am_chat_tag(e, levels[value]);
    sq_am_chat_tag(e, "<|end_message|>");
}

static void sq_am_chat_block(encoder *e, const sq_chat_message *m, const char *kind, const char *p, size_t n) {
    static const char *roles[] = {"<|message_system|>", "<|message_system|>", "<|message_user|>",
                                  "<|message_model|>"};
    sq_am_chat_tag(e, roles[m->role]);
    sq_am_chat_append(e, m->name, m->name_bytes, 0);
    sq_am_chat_tag(e, kind);
    sq_am_chat_append(e, p, n, 0);
    sq_am_chat_tag(e, "<|end_message|>");
}

static uint32_t sq_am_chat_pass(encoder *e, const sq_chat_message *m, size_t count, const sq_chat_options *o) {
    bool emitted = false;
    uint32_t prefix = 0;
    for (size_t i = 0; i < count && e->status == SQ_OK; i++) {
        bool sys = m[i].role <= SQ_CHAT_DEVELOPER;
        if (!emitted && !sys) {
            sq_am_chat_effort(e, o->effort);
            emitted = true;
            prefix = (uint32_t)e->count;
        }
        bool reasoning =
            m[i].role == SQ_CHAT_ASSISTANT && o->keep_history_thinking && m[i].reasoning_bytes;
        if (reasoning)
            sq_am_chat_block(e, m + i, "<|content_thinking|>", m[i].reasoning, m[i].reasoning_bytes);
        bool text = m[i].content && (m[i].content_bytes || !reasoning);
        if (text)
            sq_am_chat_block(e, m + i, "<|content_text|>", m[i].content, m[i].content_bytes);
        if (m[i].role == SQ_CHAT_ASSISTANT && (reasoning || text))
            sq_am_chat_tag(e, "<|content_model_end_sampling|>");
        if (sys && !emitted)
            prefix = (uint32_t)e->count;
    }
    if (!emitted) {
        sq_am_chat_effort(e, o->effort);
        prefix = (uint32_t)e->count;
    }
    if (!o->enable_thinking)
        sq_am_chat_tag(e, "<|message_model|><|content_text|>");
    return prefix;
}

sq_status sq_chat_encode(const sq_tokenizer *t, const sq_chat_message *m, size_t count,
                         const sq_chat_options *input, sq_tokenizer_scratch *scratch, int32_t *out,
                         size_t capacity, size_t *needed, uint32_t *prefix) {
    if (needed)
        *needed = 0;
    if (prefix)
        *prefix = 0;
    if (!t || !m || !count || !scratch || !needed || !prefix || (!out && capacity))
        return sq_error(SQ_INVALID_ARGUMENT, "invalid chat arguments");
    if (count > 1024)
        return sq_error(SQ_LIMIT, "chat exceeds 1024 messages");
    sq_chat_options o = SQ_CHAT_OPTIONS_INIT;
    if (input) {
        if (input->struct_size < sizeof o || input->api_version != SQ_API_VERSION)
            return sq_error(SQ_INVALID_ARGUMENT, "chat options size/version");
        o = *input;
    }
    if (o.effort > SQ_THINK_MAX || o.keep_history_thinking > 1 || o.enable_thinking > 1 ||
        o.reserved)
        return sq_error(SQ_INVALID_ARGUMENT, "invalid chat options");
    size_t bytes = 0;
    for (size_t i = 0; i < count; i++) {
        if (m[i].role > SQ_CHAT_ASSISTANT || m[i].reserved || (!m[i].content && !m[i].reasoning) ||
            (!m[i].content && m[i].content_bytes) || (!m[i].reasoning && m[i].reasoning_bytes) ||
            (!m[i].name && m[i].name_bytes) ||
            (m[i].role != SQ_CHAT_ASSISTANT && (!m[i].content || m[i].reasoning_bytes)))
            return sq_error(SQ_INVALID_ARGUMENT, "invalid text chat message");
        if (m[i].name_bytes > 128 || !sq_size_add(bytes, m[i].content_bytes, &bytes) ||
            !sq_size_add(bytes, m[i].reasoning_bytes, &bytes) ||
            !sq_size_add(bytes, m[i].name_bytes, &bytes) || bytes > 32u * 1024u * 1024u)
            return sq_error(SQ_LIMIT, "chat text/name limit exceeded");
        if (!sq_am_chat_utf8(m[i].content, m[i].content_bytes) ||
            !sq_am_chat_utf8(m[i].reasoning, m[i].reasoning_bytes) || !sq_am_chat_utf8(m[i].name, m[i].name_bytes))
            return sq_error(SQ_FORMAT, "chat text is not UTF-8");
    }
    const char *tags[] = {"<|message_system|>",
                          "<|message_user|>",
                          "<|message_model|>",
                          "<|content_text|>",
                          "<|content_thinking|>",
                          "<|end_message|>",
                          "<|content_model_end_sampling|>"};
    for (size_t i = 0; i < sizeof tags / sizeof *tags; i++)
        if (!sq_am_chat_marker(t, tags[i]))
            return sq_error(SQ_UNSUPPORTED, "chat protocol marker missing");
    encoder e = {t, scratch, NULL, 0, 0, SQ_OK};
    uint32_t system = sq_am_chat_pass(&e, m, count, &o);
    if (e.status != SQ_OK)
        return sq_error(e.status, "chat sizing failed");
    *needed = e.count;
    *prefix = system;
    if (capacity < e.count)
        return sq_error(SQ_BUFFER_TOO_SMALL, "chat token buffer too small");
    e.out = out;
    e.capacity = capacity;
    e.count = 0;
    (void)sq_am_chat_pass(&e, m, count, &o);
    return sq_error(e.status, e.status == SQ_OK ? "" : "chat encoding failed");
}


/* Module: src/stream.c */
/* SPDX-License-Identifier: Apache-2.0; Copyright (c) 2026 Artalis
 * Transport-independent Unicode decoder and leftmost stop filter. Protocol
 * section classification follows the pinned Inkling server; buffers never grow. */


#include <string.h>

typedef struct {
    unsigned char bytes[4];
    size_t used, need;
} unicode;

struct sq_stream {
    sq_options allocator;
    const sq_tokenizer *tokenizer;
    sq_stream_options options;
    sq_text_callback callback;
    void *context;
    char stops[8][64];
    size_t lengths[8];
    unsigned char pending[68];
    size_t pending_bytes;
    char batch[1024];
    size_t batch_bytes;
    uint32_t batch_channel;
    unicode utf8[2];
    int32_t model, text, thinking, end, eos;
    uint32_t section, input_kind;
    size_t header_bytes;
    bool busy;
    sq_stream_info info;
};

static sq_status sq_am_stream_fail(sq_stream *s, sq_status rc, const char *message) {
    s->info.error_status = rc;
    s->info.finish_reason = SQ_STREAM_ERROR;
    return sq_error(rc, message);
}

static bool sq_am_stream_running(const sq_stream *s) {
    return s->info.finish_reason == SQ_STREAM_RUNNING;
}

static void sq_am_stream_flush(sq_stream *s) {
    if (!s->batch_bytes || !sq_am_stream_running(s))
        return;
    size_t n = s->batch_bytes;
    s->batch_bytes = 0;
    uint64_t *counter =
        s->batch_channel == SQ_STREAM_CONTENT ? &s->info.content_bytes : &s->info.reasoning_bytes;
    if (n > UINT64_MAX - *counter) {
        (void)sq_am_stream_fail(s, SQ_LIMIT, "stream byte count overflow");
        return;
    }
    *counter += n;
    if (s->callback && !s->callback(s->context, s->batch_channel, s->batch, n))
        s->info.finish_reason = SQ_STREAM_CALLBACK;
}

static void sq_am_stream_emit(sq_stream *s, uint32_t channel, const unsigned char *p, size_t n) {
    if (!sq_am_stream_running(s) || !n)
        return;
    if (s->batch_bytes && (s->batch_channel != channel || n > sizeof s->batch - s->batch_bytes))
        sq_am_stream_flush(s);
    if (!sq_am_stream_running(s))
        return;
    s->batch_channel = channel;
    memcpy(s->batch + s->batch_bytes, p, n);
    s->batch_bytes += n;
}

/* Returns byte indexes; all stop strings and pending input are valid UTF-8,
 * so a match/prefix start is necessarily a character boundary. */
static void sq_am_stream_scan(const sq_stream *s, size_t *complete, size_t *potential) {
    *complete = *potential = s->pending_bytes;
    for (size_t i = 0; i < s->pending_bytes; i++)
        for (size_t j = 0; j < s->options.stop_count; j++) {
            size_t available = s->pending_bytes - i, n = s->lengths[j];
            if (available >= n) {
                if (!memcmp(s->pending + i, s->stops[j], n) && i < *complete)
                    *complete = i;
            } else if (!memcmp(s->pending + i, s->stops[j], available) && i < *potential)
                *potential = i;
        }
}

static void sq_am_stream_filter(sq_stream *s, const unsigned char *p, size_t n, bool final) {
    if (!sq_am_stream_running(s))
        return;
    if (n) {
        memcpy(s->pending + s->pending_bytes, p, n);
        s->pending_bytes += n;
    }
    size_t complete, potential;
    sq_am_stream_scan(s, &complete, &potential);
    if (complete < s->pending_bytes && (final || potential >= complete)) {
        sq_am_stream_emit(s, SQ_STREAM_CONTENT, s->pending, complete);
        sq_am_stream_flush(s);
        if (sq_am_stream_running(s))
            s->info.finish_reason = SQ_STREAM_STOP;
        s->pending_bytes = 0;
        return;
    }
    size_t ready = final ? s->pending_bytes : (complete < potential ? complete : potential);
    sq_am_stream_emit(s, SQ_STREAM_CONTENT, s->pending, ready);
    memmove(s->pending, s->pending + ready, s->pending_bytes - ready);
    s->pending_bytes -= ready;
}

static void sq_am_stream_codepoint(sq_stream *s, uint32_t channel, const unsigned char *p, size_t n) {
    if (channel == SQ_STREAM_CONTENT)
        sq_am_stream_filter(s, p, n, false);
    else
        sq_am_stream_emit(s, channel, p, n);
}

static void sq_am_stream_replacement(sq_stream *s, uint32_t channel) {
    if (!s->options.replace_invalid_utf8) {
        (void)sq_am_stream_fail(s, SQ_FORMAT, "invalid or incomplete stream UTF-8");
        return;
    }
    s->info.utf8_replacements++;
    static const unsigned char bad[] = {0xef, 0xbf, 0xbd};
    sq_am_stream_codepoint(s, channel, bad, 3);
}

static void sq_am_stream_byte(sq_stream *s, uint32_t channel, unsigned char b) {
    unicode *u = &s->utf8[channel];
    for (;;) {
        if (!sq_am_stream_running(s))
            return;
        if (!u->used) {
            if (b < 0x80) {
                sq_am_stream_codepoint(s, channel, &b, 1);
                return;
            }
            u->need = b >= 0xc2 && b <= 0xdf   ? 2
                      : b >= 0xe0 && b <= 0xef ? 3
                      : b >= 0xf0 && b <= 0xf4 ? 4
                                               : 0;
            if (!u->need) {
                sq_am_stream_replacement(s, channel);
                return;
            }
            u->bytes[0] = b;
            u->used = 1;
            return;
        }
        bool valid = b >= 0x80 && b <= 0xbf;
        if (u->used == 1) {
            if (u->bytes[0] == 0xe0 && b < 0xa0)
                valid = false;
            if (u->bytes[0] == 0xed && b > 0x9f)
                valid = false;
            if (u->bytes[0] == 0xf0 && b < 0x90)
                valid = false;
            if (u->bytes[0] == 0xf4 && b > 0x8f)
                valid = false;
        }
        if (!valid) {
            u->used = 0;
            sq_am_stream_replacement(s, channel);
            continue;
        }
        u->bytes[u->used++] = b;
        if (u->used == u->need) {
            u->used = 0;
            sq_am_stream_codepoint(s, channel, u->bytes, u->need);
        }
        return;
    }
}

static void sq_am_stream_finish_unicode(sq_stream *s, uint32_t channel) {
    if (s->utf8[channel].used) {
        s->utf8[channel].used = 0;
        sq_am_stream_replacement(s, channel);
    }
}

static void sq_am_stream_finish(sq_stream *s, uint32_t reason) {
    if (!sq_am_stream_running(s))
        return;
    sq_am_stream_finish_unicode(s, SQ_STREAM_REASONING);
    sq_am_stream_finish_unicode(s, SQ_STREAM_CONTENT);
    sq_am_stream_filter(s, NULL, 0, true);
    sq_am_stream_flush(s);
    if (sq_am_stream_running(s))
        s->info.finish_reason = reason;
}

static bool sq_am_stream_valid_utf8(const char *p, size_t n) {
    size_t at = 0;
    uint32_t cp;
    while (at < n)
        if (!sq_utf8_next((const unsigned char *)p, n, &at, &cp))
            return false;
    return true;
}

static int32_t sq_am_stream_special(const sq_tokenizer *t, const char *p) {
    int32_t id = sq_special_lookup(t, p, strlen(p));
    return id >= 0 && t->entries[id].special ? id : -1;
}

sq_status sq_stream_create(const sq_tokenizer *t, const sq_stream_options *input,
                           const sq_options *allocator, sq_text_callback callback, void *context,
                           sq_stream **out) {
    if (out)
        *out = NULL;
    if (!out)
        return sq_error(SQ_INVALID_ARGUMENT, "missing stream output");
    sq_stream_options o = SQ_STREAM_OPTIONS_INIT;
    if (input) {
        if (input->struct_size < sizeof o || input->api_version != SQ_API_VERSION)
            return sq_error(SQ_INVALID_ARGUMENT, "stream options size/version");
        o = *input;
    }
    if (o.parse_chat > 1 || o.replace_invalid_utf8 > 1 || o.reserved || (o.stop_count && !o.stops))
        return sq_error(SQ_INVALID_ARGUMENT, "invalid stream options");
    if (o.stop_count > 8)
        return sq_error(SQ_LIMIT, "at most eight stop strings");
    for (size_t i = 0; i < o.stop_count; i++) {
        if (!o.stops[i].data || !o.stops[i].bytes)
            return sq_error(SQ_INVALID_ARGUMENT, "empty stop string");
        if (o.stops[i].bytes > 64)
            return sq_error(SQ_LIMIT, "stop string exceeds 64 bytes");
        if (!sq_am_stream_valid_utf8(o.stops[i].data, o.stops[i].bytes))
            return sq_error(SQ_FORMAT, "stop string is not UTF-8");
    }
    int32_t ids[5] = {-1, -1, -1, -1, -1};
    if (o.parse_chat) {
        if (!t)
            return sq_error(SQ_INVALID_ARGUMENT, "chat stream needs a tokenizer");
        const char *names[] = {"<|message_model|>", "<|content_text|>", "<|content_thinking|>",
                               "<|end_message|>", "<|content_model_end_sampling|>"};
        for (unsigned i = 0; i < 5; i++)
            if ((ids[i] = sq_am_stream_special(t, names[i])) < 0)
                return sq_error(SQ_UNSUPPORTED, "stream protocol marker missing");
    } else if (t)
        ids[4] = sq_am_stream_special(t, "<|content_model_end_sampling|>");
    sq_options a;
    sq_status rc = sq_options_resolve(allocator, &a);
    if (rc != SQ_OK)
        return rc;
    sq_stream *s = a.allocate(a.context, sizeof *s);
    if (!s)
        return sq_error(SQ_OUT_OF_MEMORY, "allocate stream");
    memset(s, 0, sizeof *s);
    s->allocator = a;
    s->tokenizer = t;
    s->options = o;
    s->options.stops = NULL;
    s->model = ids[0];
    s->text = ids[1];
    s->thinking = ids[2];
    s->end = ids[3];
    s->eos = ids[4];
    for (size_t i = 0; i < o.stop_count; i++) {
        memcpy(s->stops[i], o.stops[i].data, o.stops[i].bytes);
        s->lengths[i] = o.stops[i].bytes;
    }
    (void)sq_stream_reset(s, callback, context);
    *out = s;
    return sq_error(SQ_OK, "");
}

sq_status sq_stream_reset(sq_stream *s, sq_text_callback callback, void *context) {
    if (!s)
        return sq_error(SQ_INVALID_ARGUMENT, "missing stream");
    if (s->busy)
        return sq_error(SQ_BUSY, "stream callback active");
    s->callback = callback;
    s->context = context;
    s->pending_bytes = s->batch_bytes = s->header_bytes = 0;
    s->section = s->input_kind = 0;
    memset(s->utf8, 0, sizeof s->utf8);
    s->info = (sq_stream_info)SQ_STREAM_INFO_INIT;
    return sq_error(SQ_OK, "");
}

static sq_status sq_am_stream_result(sq_stream *s) {
    return sq_error(s->info.error_status, s->info.error_status ? "stream decoding failed" : "");
}

static sq_status sq_am_stream_begin(sq_stream *s, uint32_t kind) {
    if (!s)
        return sq_error(SQ_INVALID_ARGUMENT, "missing stream");
    if (s->busy)
        return sq_error(SQ_BUSY, "stream callback active");
    if (s->input_kind && s->input_kind != kind)
        return sq_error(SQ_INVALID_ARGUMENT, "cannot mix byte and token input");
    return sq_am_stream_result(s);
}

sq_status sq_stream_push_bytes(sq_stream *s, const void *data, size_t n) {
    if ((!data && n) || n > 32u * 1024u * 1024u)
        return sq_error(SQ_INVALID_ARGUMENT, "invalid stream byte span");
    sq_status rc = sq_am_stream_begin(s, 1);
    if (rc != SQ_OK)
        return rc;
    if (!sq_am_stream_running(s))
        return sq_am_stream_result(s);
    s->busy = true;
    s->input_kind = 1;
    const unsigned char *p = data;
    for (size_t i = 0; i < n && sq_am_stream_running(s); i++)
        sq_am_stream_byte(s, SQ_STREAM_CONTENT, p[i]);
    sq_am_stream_flush(s);
    s->busy = false;
    return sq_am_stream_result(s);
}

sq_status sq_stream_push_token(sq_stream *s, int32_t id) {
    sq_status rc = sq_am_stream_begin(s, 2);
    if (rc != SQ_OK)
        return rc;
    if (!s->tokenizer)
        return sq_error(SQ_INVALID_ARGUMENT, "token stream needs a tokenizer");
    const void *data = NULL;
    size_t n = 0;
    rc = sq_tokenizer_decode(s->tokenizer, id, 0, &data, &n);
    if (rc != SQ_OK)
        return rc;
    if (!sq_am_stream_running(s))
        return sq_am_stream_result(s);
    s->busy = true;
    s->input_kind = 2;
    if (s->info.tokens == UINT64_MAX) {
        (void)sq_am_stream_fail(s, SQ_LIMIT, "stream token count overflow");
        goto done;
    }
    s->info.tokens++;
    if (id == s->eos) {
        sq_am_stream_finish(s, SQ_STREAM_EOS);
        goto done;
    }
    if (s->options.parse_chat && s->tokenizer->entries[id].special) {
        if (id == s->model || id == s->text || id == s->thinking || id == s->end) {
            sq_am_stream_finish_unicode(s, s->section == 2 ? SQ_STREAM_REASONING : SQ_STREAM_CONTENT);
            sq_am_stream_flush(s);
            s->section = id == s->model ? 1 : id == s->thinking ? 2 : 0;
            s->header_bytes = 0;
        } else
            (void)sq_am_stream_fail(s, SQ_UNSUPPORTED, "unsupported generated tool/multimodal/control section");
        goto done;
    }
    if (!s->options.parse_chat && s->tokenizer->entries[id].special)
        goto done;
    if (s->section == 1) {
        if (n > 1024 - s->header_bytes)
            (void)sq_am_stream_fail(s, SQ_LIMIT, "model header exceeds 1024 bytes");
        else
            s->header_bytes += n;
        goto done;
    }
    for (size_t i = 0; i < n && sq_am_stream_running(s); i++)
        sq_am_stream_byte(s, s->section == 2 ? SQ_STREAM_REASONING : SQ_STREAM_CONTENT,
             ((const unsigned char *)data)[i]);
done:
    sq_am_stream_flush(s);
    s->busy = false;
    return sq_am_stream_result(s);
}

sq_status sq_stream_finish(sq_stream *s, uint32_t reason) {
    if (!s || (reason != SQ_STREAM_LENGTH && reason != SQ_STREAM_CANCELLED))
        return sq_error(SQ_INVALID_ARGUMENT, "invalid stream finish");
    if (s->busy)
        return sq_error(SQ_BUSY, "stream callback active");
    s->busy = true;
    sq_am_stream_finish(s, reason);
    s->busy = false;
    return sq_am_stream_result(s);
}

sq_status sq_stream_get_info(const sq_stream *s, sq_stream_info *out) {
    if (!s || !out || out->struct_size < sizeof *out || out->api_version != SQ_API_VERSION)
        return sq_error(SQ_INVALID_ARGUMENT, "initialize stream info");
    if (s->busy)
        return sq_error(SQ_BUSY, "stream callback active");
    *out = s->info;
    return sq_error(SQ_OK, "");
}

sq_status sq_stream_destroy(sq_stream **out) {
    if (!out)
        return sq_error(SQ_INVALID_ARGUMENT, "missing stream handle");
    sq_stream *s = *out;
    if (!s)
        return sq_error(SQ_OK, "");
    if (s->busy)
        return sq_error(SQ_BUSY, "stream callback active");
    sq_options a = s->allocator;
    *out = NULL;
    a.release(a.context, s);
    return sq_error(SQ_OK, "");
}


