static void *sq_am_engine_bind_address(sq_gpu_weights *w, uint64_t offset) {
    return offset == SQ_WEIGHT_NO_OFFSET ? NULL : (unsigned char *)w->arena + (size_t)offset;
}

static sq_status sq_am_engine_bind_bind(sq_gpu_weights *w, const char *label, void *out, uint32_t type) {
    for (size_t i = 0; i < w->view_count; i++) {
        const sq_weight_view *v = &w->views[i];
        if (strcmp(label, v->label))
            continue;
        if (v->type != type)
            return sq_error(SQ_FORMAT, "AR weight type mismatch");
        if (type == SQ_WEIGHT_RAW) {
            void *p = sq_am_engine_bind_address(w, v->data);
            memcpy(out, &p, sizeof p);
        } else if (type == SQ_WEIGHT_LINEAR) {
            CLinearWeight x = {0};
            x.kind = (uint8_t)v->precision;
            x.rows = (int32_t)v->rows;
            x.cols = (int32_t)v->cols;
            x.data = sq_am_engine_bind_address(w, v->data);
            x.scales = sq_am_engine_bind_address(w, v->scales);
            x.row_scales = sq_am_engine_bind_address(w, v->row_scales);
            x.global_scale = v->global_scale;
            memcpy(out, &x, sizeof x);
        } else {
            CExpertBank x = {0};
            x.is_nvfp4 = v->precision == 2;
            x.n_experts = (int32_t)v->experts;
            x.rows = (int32_t)v->rows;
            x.cols = (int32_t)v->cols;
            x.data = sq_am_engine_bind_address(w, v->data);
            x.scales = sq_am_engine_bind_address(w, v->scales);
            x.expert_scale = sq_am_engine_bind_address(w, v->expert_scale);
            memcpy(out, &x, sizeof x);
        }
        return SQ_OK;
    }
    return sq_error(SQ_FORMAT, "missing AR weight view");
}

