void sq_ar_schedule(sq_visit out[48]) {
    unsigned i = 0;
    for (unsigned l = 0; l < 6; l++)
        out[i++] = (sq_visit){l, 0, false, l % 6 == 5};
    for (unsigned p = 0; p < 3; p++)
        for (unsigned l = 6; l < 18; l++)
            out[i++] = (sq_visit){l, p, true, l % 6 == 5};
    for (unsigned l = 18; l < 24; l++)
        out[i++] = (sq_visit){l, 0, false, l % 6 == 5};
}

