/* Module: src/engine_layout.c */
/* SPDX-License-Identifier: Apache-2.0
 * Copyright (c) 2026 tensorfish; Copyright (c) 2026 Artalis
 * Two-pass target and optional DSpark workspace layout. B<=8 matches
 * target-forward geometry; prefix checkpoints are separately owned host memory. */

static void *sq_am_engine_layout_take(sq_session *s, size_t count, size_t width) {
    size_t bytes, aligned, end;
    if (s->status != SQ_OK)
        return NULL;
    if (!sq_size_mul(count, width, &bytes) || !sq_size_align(bytes, 256, &aligned) ||
        !sq_size_add(s->offset, aligned, &end) || (s->arena && end > s->capacity)) {
        s->status = SQ_LIMIT;
        return NULL;
    }
    void *p = s->arena ? (unsigned char *)s->arena + s->offset : NULL;
    s->offset = end;
    s->allocations++;
    return p;
}

void sq_ar_layout(sq_session *s, size_t groups) {
    s->offset = s->allocations = 0;
    sq_ar_schedule(s->schedule);
    for (unsigned i = 0; i < 48; i++) {
        bool global = s->schedule[i].global;
        size_t cap = global ? s->config.context_tokens : 1280;
        unsigned format = global ? s->config.kv_format : 0;
        s->kv_cap[i] = (int32_t)cap;
        size_t width = format == 0 ? 2048 : format == 1 ? 1024 : 512;
        s->k_cache[i] = sq_am_engine_layout_take(s, cap, width);
        s->v_cache[i] = sq_am_engine_layout_take(s, cap, width);
        s->k_scale[i] = format ? sq_am_engine_layout_take(s, cap, format == 1 ? 16 : 32) : NULL;
        s->v_scale[i] = format ? sq_am_engine_layout_take(s, cap, format == 1 ? 16 : 32) : NULL;
        s->k_ring[i] = sq_am_engine_layout_take(s, 16 * 1024, 4);
        s->v_ring[i] = sq_am_engine_layout_take(s, 16 * 1024, 4);
        s->attn_ring[i] = sq_am_engine_layout_take(s, 16 * 2304, 4);
        s->mlp_ring[i] = sq_am_engine_layout_take(s, 16 * 2304, 4);
    }
#define F(name, n) s->name = sq_am_engine_layout_take(s, (n), 4)
#define H(name, n) s->name = sq_am_engine_layout_take(s, (n), 2)
    if (s->weights->config.with_mtp) {
        for (unsigned i = 0; i < 3; i++) {
            size_t cap = i != 1                              ? 1032
                         : s->config.context_tokens > 524288 ? 65536
                                                             : s->config.context_tokens;
            unsigned format = i != 1 ? 0 : s->config.kv_format;
            s->ds_cap[i] = (int32_t)cap;
            size_t width = format == 0 ? 2048 : format == 1 ? 1024 : 512;
            s->ds_k[i] = sq_am_engine_layout_take(s, cap, width);
            s->ds_v[i] = sq_am_engine_layout_take(s, cap, width);
            s->ds_ks[i] = format ? sq_am_engine_layout_take(s, cap, format == 1 ? 16 : 32) : NULL;
            s->ds_vs[i] = format ? sq_am_engine_layout_take(s, cap, format == 1 ? 16 : 32) : NULL;
        }
        F(ds_f_ring, 16 * 2304);
        F(taps, 4 * 8 * 2304);
        F(ds_mix, 3 * 8 * 2304);
        F(ds_kv, 8 * 2 * 1024);
        F(ds_ws, 2000000);
        F(d_anchor, 1);
        F(d_drafts, 7);
        F(d_accepted, 8);
        F(d_num_acc, 1);
        F(d_draft_is_delta, 1);
        F(d_draft_probs, 7 * 200058);
        F(d_draft_q_sel, 7);
        F(d_conf, 7);
        F(d_width, 1);
    }
    F(split_buf, 2050000);
    F(d_pos, 1);
    F(d_tokens, 8);
    F(d_next_tokens, 8);
    F(hidden, 8 * 2304);
    F(prelude, 8 * 2304);
    F(partial, 8 * 2304);
    F(blocks, 8 * 4 * 2304);
    F(saved, 8 * 2304);
    F(prior_last, 8 * 2304);
    for (unsigned i = 0; i < 3; i++) {
        s->attn_in[i] = sq_am_engine_layout_take(s, 8 * 2304, 4);
        s->attn_in_h[i] = sq_am_engine_layout_take(s, 8 * 2304, 2);
    }
    F(qrgs, 8 * 6552);
    F(k_proj, 8 * 1024);
    F(v_proj, 8 * 1024);
    F(attn_gated, 8 * 3072);
    H(attn_gated_h, 8 * 3072);
    F(o_proj, 8 * 2304);
    F(residual, 8 * 2304);
    F(mlp_in, 8 * 2304);
    F(mlp_normed, 8 * 2304);
    H(mlp_normed_h, 8 * 2304);
    F(ctrl_msg, 3 * 8 * 2304);
    F(ctrl_cat, 3 * 8 * 2 * 2304);
    F(ctrl_d, 3 * 8 * 64);
    F(router_logits, 8 * 128);
    F(route_ids, 8 * 8);
    F(route_w, 8 * 8);
    s->exp_groups = sq_am_engine_layout_take(s, groups, 1);
    H(moe_act_h, 8 * 8 * 1152);
    F(moe_down, 8 * 2304);
    F(lm_blk_val, 8 * 1024);
    F(lm_blk_idx, 8 * 1024);
    F(lm_logits, 8 * 200058);
    s->d_sample_cfg = sq_am_engine_layout_take(s, 1, sizeof(CSampleConfig));
    s->d_loopcd_cfg = sq_am_engine_layout_take(s, 1, sizeof(CLoopCDConfig));
    F(loopcd_h1, 8 * 2304);
    F(loopcd_h2, 8 * 2304);

    enum { P = 2048 };

    if (s->weights->config.with_mtp) {
        F(p_taps, 4 * P * 2304);
    }
    F(p_tokens, P);
    F(p_pos_vec, P / 8);
    F(p_hidden, P * 2304);
    F(p_prelude, P * 2304);
    F(p_partial, P * 2304);
    F(p_blocks, P * 4 * 2304);
    F(p_saved, P * 2304);
    F(p_prior_last, P * 2304);
    for (unsigned i = 0; i < 3; i++) {
        s->p_attn_in[i] = sq_am_engine_layout_take(s, P * 2304, 4);
        s->p_attn_in_h[i] = sq_am_engine_layout_take(s, P * 2304, 2);
    }
    F(p_qrgs, P * 6552);
    F(p_k_proj, P * 1024);
    F(p_v_proj, P * 1024);
    H(p_attn_gated_h, P * 3072);
    F(p_o_proj, P * 2304);
    F(p_residual, P * 2304);
    F(p_mlp_in, P * 2304);
    F(p_mlp_normed, P * 2304);
    H(p_mlp_normed_h, P * 2304);
    F(p_router_logits, P * 128);
    F(p_route_ids, P * 8);
    F(p_route_w, P * 8);
    F(p_exp_offsets, 1024);
    F(p_sorted_tok, P * 8);
    F(p_sorted_slot, P * 8);
    F(p_sorted_w, P * 8);
    H(p_moe_act_h, P * 8 * 1152);
    F(p_moe_slot_out, P * 8 * 2304);
    H(p_w_f16, 6552 * 2304);
    F(p_ctrl_msg, P * 2304);
    H(p_ctrl_cat_h, P * 4608);
    F(p_ctrl_d, P * 64);
    H(p_ctrl_d_h, P * 64);
    s->p_ctrl_f = s->p_qrgs;
    s->p_ctrl_g = s->p_qrgs ? s->p_qrgs + P * 2304 : NULL;
#undef F
#undef H
}

#undef F
#undef H

/* Module: src/engine_forward.c */
/* SPDX-License-Identifier: Apache-2.0
 * Copyright (c) 2026 tensorfish; Copyright (c) 2026 Artalis
 * Target-forward translation of pinned Engine.record_target_forward. Optional
 * DSpark commit/verification; ablation and LoopCD remain disabled. */

void sq_ar_forward(sq_session *s, int32_t batch, bool lm) {
    const sq_ar_model *w = &s->model;
    void *stream = s->stream;
    int32_t blocks = 0;
    bool prior = false, pending = false;
    squid_launch_embed_norm(w->embed, w->embed_norm, s->d_tokens, s->hidden, batch, stream);
    for (unsigned vi = 0; vi < 48; vi++) {
        sq_visit v = s->schedule[vi];
        unsigned l = v.layer;
        const sq_layer *lw = &w->layers[l];
        float *pre_tap = NULL;
        if (v.loop && l == 6) {
            if (v.pass == 0)
                pre_tap = s->prelude;
            else {
                squid_launch_extract_block(s->blocks, 4, 2, s->saved, batch, stream);
                squid_launch_rmsnorm(s->hidden, NULL, s->prior_last, batch, 2304, 2304, 1e-6f,
                                     stream);
                sq_ar_check(s,
                            squid_cuda_memcpy_d2d_async(s->hidden, s->prelude,
                                                        (size_t)batch * 2304 * 4, stream),
                            "restore prelude");
                blocks = 1;
                prior = true;
            }
        }
        if (s->use_mtp && (vi == 5 || vi == 23 || vi == 41)) {
            unsigned slot = vi == 5 ? 0 : vi == 23 ? 1 : 2;
            pre_tap = s->taps + (size_t)slot * (size_t)batch * 2304;
        }
        bool use_prior = v.loop && prior, distinct = v.global || use_prior;
        float *partial = l % 6 == 0 ? s->partial : NULL;
        bool half = lw->w_qrgs.kind != 0;
        const void *n[3] = {NULL, NULL, NULL};
        float *o[3] = {NULL, NULL, NULL};
        void *oh[3] = {NULL, NULL, NULL};
        int32_t count = 1;
        if (!distinct) {
            n[0] = lw->attn_norm;
            o[0] = s->attn_in[0];
            oh[0] = half ? s->attn_in_h[0] : NULL;
        } else if (v.global && !use_prior) {
            n[0] = lw->q_in_norm;
            n[1] = lw->k_in_norm;
            n[2] = lw->v_in_norm;
            for (unsigned j = 0; j < 3; j++) {
                o[j] = s->attn_in[j];
                oh[j] = half ? s->attn_in_h[j] : NULL;
            }
            count = 3;
        } else if (v.global) {
            for (unsigned j = 0; j < 3; j++)
                o[j] = s->attn_in[j];
            count = 3;
        } else
            o[0] = s->mlp_in;
        if (pending) {
            const sq_layer *prev = &w->layers[s->schedule[vi - 1].layer];
            squid_launch_mega_mlp_post_next_depth_norm(
                s->moe_down, 0, prev->mlp_sconv_w, s->mlp_ring[vi - 1], s->residual, s->hidden,
                pre_tap, NULL, partial, s->blocks, blocks, w->attn_queries[l - 1], n[0], n[1], n[2],
                o[0], o[1], o[2], oh[0], oh[1], oh[2], count, batch, s->d_pos, NULL, NULL, NULL,
                vi == 42 ? s->loopcd_h1 : NULL, vi == 42 ? s->loopcd_h2 : NULL,
                vi == 42 ? s->d_loopcd_cfg : NULL, stream);
            pending = false;
        } else
            squid_launch_fused_depth_norm(s->hidden, partial, s->blocks, blocks,
                                          l ? w->attn_queries[l - 1] : NULL, n[0], n[1], n[2], o[0],
                                          o[1], o[2], oh[0], oh[1], oh[2], count, batch, stream);
        if (use_prior) {
            unsigned loc = l - 6;
            float *xs[3] = {v.global ? s->attn_in[0] : s->mlp_in,
                            v.global ? s->attn_in[1] : s->mlp_in,
                            v.global ? s->attn_in[2] : s->mlp_in};
            float *outs[3] = {s->attn_in[0], s->attn_in[1], s->attn_in[2]};
            void *out_h[3] = {s->attn_in_h[0], s->attn_in_h[1], s->attn_in_h[2]};
            const float *queries[3] = {w->cross_pass_queries + 2 * loc * 2304,
                                       w->cross_pass_kv_queries + 2 * loc * 2304,
                                       w->cross_pass_kv_queries + (2 * loc + 1) * 2304};
            const CControllerWeights *cw[3] = {&lw->ctrl[0], &lw->ctrl[1], &lw->ctrl[2]};
            const void *norms[3] = {v.global ? lw->q_in_norm : lw->attn_norm,
                                    v.global ? lw->k_in_norm : lw->attn_norm,
                                    v.global ? lw->v_in_norm : lw->attn_norm};
            if (s->weights->config.mode == 2)
                squid_launch_controller_mega_nvfp4(xs, s->saved, s->prior_last, queries, cw, norms,
                                                   outs, half ? out_h : NULL, 3, batch, stream);
            else
                squid_launch_controller_merge_batched(
                    xs, s->saved, s->prior_last, queries, cw, norms, outs, half ? out_h : NULL, 3,
                    s->ctrl_msg, s->ctrl_cat, s->ctrl_d, batch, stream);
        }
        float *in_q = s->attn_in[0], *in_k = s->attn_in[distinct ? 1 : 0],
              *in_v = s->attn_in[distinct ? 2 : 0];
        if (half)
            squid_launch_qkvrg_fused(&lw->w_qrgs, &lw->w_k, &lw->w_v, s->attn_in_h[0],
                                     s->attn_in_h[distinct ? 1 : 0], s->attn_in_h[distinct ? 2 : 0],
                                     s->qrgs, s->k_proj, s->v_proj, batch, stream);
        else {
            squid_launch_linear(&lw->w_qrgs, in_q, s->qrgs, batch, 0, stream);
            squid_launch_linear(&lw->w_k, in_k, s->k_proj, batch, 0, stream);
            squid_launch_linear(&lw->w_v, in_v, s->v_proj, batch, 0, stream);
        }
        if (v.global)
            squid_launch_mega_global_sconv_prep_store(
                s->qrgs, s->k_proj, s->v_proj, in_k, in_v, lw->k_sconv_w, lw->v_sconv_w,
                lw->k_sconv_proj, lw->v_sconv_proj, s->k_ring[vi], s->v_ring[vi], lw->q_clip_scale,
                lw->rel_clip_scale, s->k_cache[vi], s->v_cache[vi], s->k_scale[vi], s->v_scale[vi],
                (uint8_t)s->config.kv_format, s->kv_cap[vi], batch, s->d_pos, stream);
        else
            squid_launch_mega_local_sconv_prep_store(
                s->qrgs, s->k_proj, s->v_proj, lw->k_sconv_w, lw->v_sconv_w, s->k_ring[vi],
                s->v_ring[vi], lw->q_clip_scale, lw->rel_clip_scale, s->k_cache[vi], s->v_cache[vi],
                s->kv_cap[vi], batch, s->d_pos, stream);
        squid_launch_relative_attention_gated(
            s->qrgs, lw->rel_logits_proj, s->k_cache[vi], s->v_cache[vi], s->k_scale[vi],
            s->v_scale[vi], v.global ? (uint8_t)s->config.kv_format : 0, s->split_buf,
            half ? NULL : s->attn_gated, half ? s->attn_gated_h : NULL, s->kv_cap[vi],
            v.global ? 0 : 1024, batch, s->d_pos, stream);
        if (half)
            squid_launch_linear_h(&lw->w_o, s->attn_gated_h, s->o_proj, batch, 0, stream);
        else
            squid_launch_linear(&lw->w_o, s->attn_gated, s->o_proj, batch, 0, stream);
        bool boundary = l % 6 == 0;
        squid_launch_mega_attn_post_mlp_in(
            s->o_proj, lw->attn_sconv_w, s->attn_ring[vi], s->hidden, s->partial, s->blocks, blocks,
            boundary ? 1 : 0, s->residual, w->mlp_queries[l], use_prior ? NULL : lw->mlp_norm,
            use_prior ? s->mlp_in : s->mlp_normed, use_prior ? NULL : s->mlp_normed_h, batch,
            s->d_pos, NULL, NULL, NULL, stream);
        if (boundary)
            blocks++;
        if (use_prior) {
            float *xs[1] = {s->mlp_in}, *outs[1] = {s->mlp_normed};
            void *outs_h[1] = {s->mlp_normed_h};
            const float *q[3] = {w->cross_pass_queries + (2 * (l - 6) + 1) * 2304, NULL, NULL};
            const CControllerWeights *cw[3] = {&lw->ctrl[3], NULL, NULL};
            const void *norms[3] = {lw->mlp_norm, NULL, NULL};
            if (s->weights->config.mode == 2)
                squid_launch_controller_mega_nvfp4(xs, s->saved, s->prior_last, q, cw, norms, outs,
                                                   outs_h, 1, batch, stream);
            else
                squid_launch_controller_merge_batched(xs, s->saved, s->prior_last, q, cw, norms,
                                                      outs, outs_h, 1, s->ctrl_msg, s->ctrl_cat,
                                                      s->ctrl_d, batch, stream);
        }
        if (s->weights->config.mode == 2)
            squid_launch_route_topk_nvfp4(s->mlp_normed_h, &lw->router_nvfp4, lw->router_bias,
                                          s->router_logits, s->route_ids, s->route_w, NULL, batch,
                                          stream);
        else
            squid_launch_route_topk(s->mlp_normed, lw->router_w, lw->router_bias, s->router_logits,
                                    s->route_ids, s->route_w, NULL, batch, stream);
        squid_launch_moe_gate_up_h(&lw->w13, s->mlp_normed_h, s->route_ids, s->exp_groups,
                                   s->moe_act_h, batch, stream);
        squid_launch_moe_down_h(&lw->w2, s->moe_act_h, s->route_ids, s->route_w, s->exp_groups,
                                s->moe_down, batch, stream);
        if (vi == 17 || vi == 29) {
            squid_launch_mega_mlp_post_res(
                s->moe_down, 0, lw->mlp_sconv_w, s->mlp_ring[vi], s->residual, s->hidden,
                vi == 17 ? s->loopcd_h1 : s->loopcd_h2, batch, s->d_pos, NULL, NULL, NULL, stream);
            pending = false;
        } else
            pending = true;
        if (s->status != SQ_OK)
            return;
    }
    squid_launch_mega_mlp_post_next_depth_norm(
        s->moe_down, 0, w->layers[s->schedule[47].layer].mlp_sconv_w, s->mlp_ring[47], s->residual,
        s->hidden, NULL, s->use_mtp ? s->taps + 3 * (size_t)batch * 2304 : NULL, NULL, s->blocks,
        blocks, w->output_query, w->final_norm, NULL, NULL, s->mlp_normed, NULL, NULL, NULL, NULL,
        NULL, 1, batch, s->d_pos, NULL, NULL, NULL, NULL, NULL, NULL, stream);
    sq_spec_commit(s, s->taps, batch, s->d_pos);
    if (lm)
        squid_launch_lm_head_argmax(
            &w->unembed, s->mlp_normed, s->d_next_tokens, s->lm_logits, s->lm_blk_val,
            s->lm_blk_idx, s->d_sample_cfg, s->d_pos, s->verifying ? s->d_drafts : NULL,
            s->verifying ? s->d_draft_probs : NULL, s->verifying ? s->d_draft_q_sel : NULL,
            s->verifying ? s->d_draft_is_delta : NULL,
            s->verifying ? w->dspark.inv_draft_vocab_ids : NULL, w->dspark.draft_vocab_size, batch,
            stream);
}


/* Module: src/engine_spec.c */
/* SPDX-License-Identifier: Apache-2.0
 * Copyright (c) 2026 tensorfish; Copyright (c) 2026 Artalis
 * Fixed-width DSpark: same draft/assemble/target/verify order as pinned Zig.
 * Commit is serialized on the owned stream; no work remains overlapped on return. */

void sq_spec_commit(sq_session *s, const float *taps, int32_t batch, const int32_t *position) {
    if (s->use_mtp && s->status == SQ_OK)
        squid_launch_dspark_commit(&s->model.dspark, taps, s->ds_k, s->ds_v, s->ds_ks, s->ds_vs,
                                   s->ds_cap, (uint8_t)s->config.kv_format, s->ds_f_ring, s->ds_mix,
                                   s->ds_kv, batch, position, s->stream);
}

void sq_spec_draft(sq_session *s, uint32_t drafts, float *confidence) {
    const void *ks[3] = {s->ds_ks[0], s->ds_ks[1], s->ds_ks[2]};
    const void *vs[3] = {s->ds_vs[0], s->ds_vs[1], s->ds_vs[2]};
    squid_launch_dspark_draft(s->model.embed, s->model.embed_norm, &s->model.dspark, s->d_anchor,
                              s->d_pos, (int32_t)drafts, s->ds_k, s->ds_v, ks, vs, s->ds_cap,
                              (uint8_t)s->config.kv_format, s->split_buf, s->ds_f_ring, s->ds_ws,
                              s->d_drafts, confidence, s->d_sample_cfg, s->d_draft_probs,
                              s->d_draft_q_sel, s->d_draft_is_delta, s->stream);
    sq_ar_check(s, sq_cuda_launch_status(), "DSpark draft launch");
}

void sq_spec_verify(sq_session *s, uint32_t drafts) {
    squid_launch_assemble_verify_tokens(s->d_anchor, s->d_drafts, s->d_tokens, (int32_t)drafts,
                                        s->stream);
    sq_spec_target(s, drafts);
}

void sq_spec_target(sq_session *s, uint32_t drafts) {
    s->verifying = true;
    sq_ar_forward(s, (int32_t)drafts + 1, true);
    s->verifying = false;
    if (s->status == SQ_OK)
        squid_launch_spec_verify(s->d_next_tokens, s->d_drafts, (int32_t)drafts + 1, s->d_accepted,
                                 s->d_num_acc, s->d_pos, s->d_anchor, s->stream);
    sq_ar_check(s, sq_cuda_launch_status(), "DSpark draft/verify launch");
}

void sq_spec_step(sq_session *s, uint32_t drafts) {
    if (s->status != SQ_OK)
        return;
    if (!s->config.use_graphs) {
        sq_spec_draft(s, drafts, NULL);
        if (s->status == SQ_OK)
            sq_spec_verify(s, drafts);
        return;
    }
    if (!s->spec_graph[drafts]) {
        sq_ar_check(s, squid_cuda_graph_begin(s->stream), "begin DSpark graph");
        if (s->status != SQ_OK)
            return;
        sq_spec_draft(s, drafts, NULL);
        if (s->status == SQ_OK)
            sq_spec_verify(s, drafts);
        sq_ar_check(s, squid_cuda_graph_end_instantiate(s->stream, &s->spec_graph[drafts]),
                    "instantiate DSpark graph");
    }
    if (s->status == SQ_OK)
        sq_ar_check(s, squid_cuda_graph_launch(s->spec_graph[drafts], s->stream),
                    "launch DSpark graph");
}


/* Module: src/engine_adaptive.c */
/* SPDX-License-Identifier: Apache-2.0
 * Copyright (c) 2026 tensorfish; Copyright (c) 2026 Artalis
 * Pinned adaptive graph scheduling: width switch, lookup verification and
 * next-draft overlap. Every exit drains work before reset or resource release. */

static void sq_am_engine_adaptive_capture_finish(sq_session *s, void **graph) {
    sq_ar_check(s, squid_cuda_graph_end_instantiate(s->stream, graph),
                "finish adaptive component capture");
}

static void sq_am_engine_adaptive_prepare(sq_session *s, float threshold) {
    if (!s->draft_graph) {
        sq_ar_check(s, squid_cuda_graph_begin(s->stream), "begin draft graph");
        if (s->status != SQ_OK)
            return;
        sq_spec_draft(s, 7, s->d_conf);
        sq_am_engine_adaptive_capture_finish(s, &s->draft_graph);
    }
    if (s->status != SQ_OK)
        return;
    if (!s->lookup_graph) {
        sq_ar_check(s, squid_cuda_graph_begin(s->stream), "begin lookup graph");
        if (s->status != SQ_OK)
            return;
        sq_spec_verify(s, 7);
        if (s->status == SQ_OK)
            sq_ar_check(s, squid_cuda_memcpy_d2h_async(s->h_count, s->d_num_acc, 4, s->stream),
                        "capture lookup count");
        if (s->status == SQ_OK)
            sq_ar_check(s, squid_cuda_memcpy_d2h_async(s->h_accepted, s->d_accepted, 32, s->stream),
                        "capture lookup output");
        sq_am_engine_adaptive_capture_finish(s, &s->lookup_graph);
    }
    if (s->status != SQ_OK || s->adaptive_threshold == threshold)
        return;
    sq_ar_check(s, sq_adaptive_cleanup(s->adaptive_state), "retire old adaptive threshold");
    if (s->status != SQ_OK)
        return;
    s->adaptive_threshold = 0;
    sq_ar_check(s,
                sq_adaptive_prepare(s->adaptive_state, s->d_anchor, s->d_drafts, s->d_conf,
                                    threshold, s->d_tokens, s->d_width, s->d_accepted,
                                    s->h_accepted, s->d_num_acc, s->h_count, s->h_width, s->stream),
                "prepare conditional graph");
    const uint32_t widths[3] = {2, 4, 8};
    for (int i = 0; i < 3 && s->status == SQ_OK; i++) {
        sq_ar_check(s, sq_adaptive_branch_begin(s->adaptive_state, i, s->stream),
                    "begin conditional branch");
        if (s->status != SQ_OK)
            break;
        sq_spec_target(s, widths[i] - 1);
        sq_ar_check(s, sq_adaptive_branch_end(s->adaptive_state), "end conditional branch");
    }
    if (s->status == SQ_OK)
        sq_ar_check(s, sq_adaptive_instantiate(s->adaptive_state), "instantiate conditional graph");
    if (s->status == SQ_OK)
        s->adaptive_threshold = threshold;
}

static void sq_am_engine_adaptive_draft(sq_session *s) {
    if (s->status != SQ_OK)
        return;
    /* Conservatively retain the in-flight marker if launch/sync fails. */
    s->draft_in_flight = true;
    int e = squid_cuda_graph_launch(s->draft_graph, s->stream);
    sq_ar_check(s, e, "launch overlapped draft");
    if (!e)
        s->decode_info.draft_launches++;
}

void sq_adaptive_step(sq_session *s, const sq_decode_options *options, bool lookup) {
    if (s->status != SQ_OK)
        return;
    sq_am_engine_adaptive_prepare(s, options->spec_threshold);
    if (s->status != SQ_OK)
        return;
    if (lookup) {
        int32_t one = 1;
        const sq_weight_backend *b = &s->weights->backend;
        sq_ar_check(s, b->copy(b->context, s->d_draft_is_delta, &one, 4, 0, s->stream),
                    "set Dirac proposal");
        if (s->status == SQ_OK)
            sq_ar_check(
                s, b->copy(b->context, s->d_drafts, (int32_t *)s->pinned + 10, 28, 0, s->stream),
                "upload lookup proposal");
        if (s->status == SQ_OK)
            sq_ar_check(s, squid_cuda_graph_launch(s->lookup_graph, s->stream),
                        "verify lookup proposal");
        if (s->status == SQ_OK)
            sq_ar_check(s, b->sync(b->context, s->stream), "finish lookup verification");
        if (s->status == SQ_OK)
            s->draft_in_flight = false;
        return;
    }
    if (!s->draft_in_flight)
        sq_am_engine_adaptive_draft(s);
    if (s->status == SQ_OK)
        sq_ar_check(s, sq_adaptive_launch(s->adaptive_state, s->stream),
                    "launch adaptive verification");
    if (s->status == SQ_OK)
        sq_ar_check(s, squid_cuda_event_record(s->done_event, s->stream),
                    "record verified-output event");
    if (s->status == SQ_OK)
        sq_am_engine_adaptive_draft(s);
    if (s->status == SQ_OK)
        sq_ar_check(s, squid_cuda_event_sync(s->done_event), "await verified outputs");
}

void sq_adaptive_drain(sq_session *s) {
    if (!s->draft_in_flight)
        return;
    int e = s->weights->backend.sync(s->weights->backend.context, s->stream);
    sq_ar_check(s, e, "drain overlapped draft");
    if (!e)
        s->draft_in_flight = false;
}


/* Module: src/engine_prefix.c */
/* SPDX-License-Identifier: Apache-2.0
 * Copyright (c) 2026 tensorfish; Copyright (c) 2026 Artalis
 * Pinned four-checkpoint local/recurrent cache and bounded global-KV shield.
 * Model, arena format and execution identity are session-owned and immutable. */

#include <string.h>

static size_t sq_am_engine_prefix_add(sq_session *s, size_t a, size_t b) {
    size_t out = 0;
    if (!sq_size_add(a, b, &out))
        s->status = SQ_LIMIT;
    return out;
}

/* Common traversal for sizing, saving and restoring. All GPU/host ranges are
 * owned by this session. Host validity is committed only after a complete sync. */
typedef struct {
    sq_session *s;
    unsigned char *host;
    size_t offset, capacity;
    int direction; /* -1 plan, 0 restore, 1 save */
} transfer;

static void sq_am_engine_prefix_span(transfer *t, void *device, size_t bytes) {
    size_t end = sq_am_engine_prefix_add(t->s, t->offset, bytes);
    if (t->s->status != SQ_OK)
        return;
    if (t->direction >= 0) {
        if (end > t->capacity || !device || !t->host) {
            t->s->status = SQ_LIMIT;
            return;
        }
        void *host = t->host + t->offset;
        const sq_weight_backend *b = &t->s->weights->backend;
        sq_ar_check(t->s,
                    b->copy(b->context, t->direction ? host : device, t->direction ? device : host,
                            bytes, t->direction, t->s->stream),
                    "prefix state transfer");
    }
    t->offset = end;
}

static void sq_am_engine_prefix_local(transfer *t) {
    sq_session *s = t->s;
    for (unsigned i = 0; i < 48; i++) {
        if (!s->schedule[i].global) {
            sq_am_engine_prefix_span(t, s->k_cache[i], (size_t)s->kv_cap[i] * 2048);
            sq_am_engine_prefix_span(t, s->v_cache[i], (size_t)s->kv_cap[i] * 2048);
        }
        sq_am_engine_prefix_span(t, s->k_ring[i], 16 * 1024 * 4);
        sq_am_engine_prefix_span(t, s->v_ring[i], 16 * 1024 * 4);
        sq_am_engine_prefix_span(t, s->attn_ring[i], 16 * 2304 * 4);
        sq_am_engine_prefix_span(t, s->mlp_ring[i], 16 * 2304 * 4);
    }
    if (s->ds_f_ring) {
        for (unsigned i = 0; i < 3; i += 2) {
            sq_am_engine_prefix_span(t, s->ds_k[i], (size_t)s->ds_cap[i] * 2048);
            sq_am_engine_prefix_span(t, s->ds_v[i], (size_t)s->ds_cap[i] * 2048);
        }
        sq_am_engine_prefix_span(t, s->ds_f_ring, 16 * 2304 * 4);
    }
}

static void sq_am_engine_prefix_pair(transfer *t, void *k, void *v, void *ks, void *vs, uint32_t n) {
    unsigned format = t->s->config.kv_format;
    sq_am_engine_prefix_span(t, k, (size_t)n * (format == 0 ? 2048 : format == 1 ? 1024 : 512));
    sq_am_engine_prefix_span(t, v, (size_t)n * (format == 0 ? 2048 : format == 1 ? 1024 : 512));
    if (format) {
        sq_am_engine_prefix_span(t, ks, (size_t)n * (format == 1 ? 16 : 32));
        sq_am_engine_prefix_span(t, vs, (size_t)n * (format == 1 ? 16 : 32));
    }
}

static void sq_am_engine_prefix_global(transfer *t, uint32_t n) {
    sq_session *s = t->s;
    for (unsigned i = 0; i < 48; i++)
        if (s->schedule[i].global)
            sq_am_engine_prefix_pair(t, s->k_cache[i], s->v_cache[i], s->k_scale[i], s->v_scale[i], n);
    if (s->ds_f_ring)
        sq_am_engine_prefix_pair(t, s->ds_k[1], s->ds_v[1], s->ds_ks[1], s->ds_vs[1],
             n < (uint32_t)s->ds_cap[1] ? n : (uint32_t)s->ds_cap[1]);
}

static void sq_am_engine_prefix_sync_transfer(sq_session *s) {
    if (s->status == SQ_OK)
        sq_ar_check(s, s->weights->backend.sync(s->weights->backend.context, s->stream),
                    "complete prefix state transfer");
}

void sq_prefix_invalidate(sq_session *s) {
    s->prefix.length = 0;
    s->prefix.live = -1;
    s->prefix.shield_tokens = 0;
    for (unsigned i = 0; i < 4; i++)
        s->prefix.checkpoints[i].valid = false;
}

void sq_prefix_free(sq_session *s) {
    sq_prefix *p = &s->prefix;
    if (p->tokens)
        s->allocator.release(s->allocator.context, p->tokens);
    if (p->shield)
        s->allocator.release(s->allocator.context, p->shield);
    for (unsigned i = 0; i < 4; i++)
        if (p->checkpoints[i].data)
            s->allocator.release(s->allocator.context, p->checkpoints[i].data);
    memset(p, 0, sizeof *p);
    p->live = -1;
}

sq_status sq_prefix_allocate(sq_session *s) {
    if (s->prefix.enabled)
        return SQ_OK;
    sq_prefix *p = &s->prefix;
    transfer l = {s, NULL, 0, 0, -1}, g = l;
    sq_am_engine_prefix_local(&l);
    sq_am_engine_prefix_global(&g, s->config.context_tokens < 4096 ? s->config.context_tokens : 4096);
    p->local_bytes = l.offset;
    p->shield_bytes = g.offset;
    size_t total = 0;
    for (unsigned i = 0; i < 4; i++)
        total = sq_am_engine_prefix_add(s, total, l.offset);
    total = sq_am_engine_prefix_add(s, total, g.offset);
    total = sq_am_engine_prefix_add(s, total, (size_t)s->config.context_tokens * 4);
    if (s->status != SQ_OK)
        return sq_error(s->status, "prefix size overflow");
    p->tokens = s->allocator.allocate(s->allocator.context, (size_t)s->config.context_tokens * 4);
    for (unsigned i = 0; i < 4 && p->tokens; i++) {
        p->checkpoints[i].data = s->allocator.allocate(s->allocator.context, l.offset);
        if (!p->checkpoints[i].data)
            break;
    }
    if (p->tokens && p->checkpoints[3].data)
        p->shield = s->allocator.allocate(s->allocator.context, g.offset);
    if (!p->shield) {
        sq_prefix_free(s);
        return sq_error(SQ_OUT_OF_MEMORY, "allocate prefix checkpoints/shield");
    }
    p->host_bytes = total;
    p->enabled = true;
    sq_prefix_invalidate(s);
    return SQ_OK;
}

void sq_prefix_save(sq_session *s, unsigned slot, uint32_t position) {
    sq_prefix *p = &s->prefix;
    if (!p->enabled || p->shield_tokens || s->status != SQ_OK || slot >= 4)
        return;
    sq_checkpoint *c = &p->checkpoints[slot];
    c->valid = false;
    transfer t = {s, c->data, 0, p->local_bytes, 1};
    sq_am_engine_prefix_local(&t);
    sq_am_engine_prefix_sync_transfer(s);
    if (s->status == SQ_OK && t.offset == p->local_bytes) {
        c->position = position;
        c->valid = true;
    }
}

uint32_t sq_prefix_begin(sq_session *s, const int32_t *tokens, uint32_t n, uint32_t max_new,
                         bool mtp) {
    sq_prefix *p = &s->prefix;
    s->prefix_info = (sq_prefix_info)SQ_PREFIX_INFO_INIT;
    s->prefix_info.host_bytes = p->host_bytes;
    if (!p->enabled)
        return 0;
    uint32_t common = 0, limit = p->length < n - 1 ? p->length : n - 1;
    while (common < limit && p->tokens[common] == tokens[common])
        common++;
    uint32_t need = n + max_new + 16;
    p->shield_tokens = 0;
    uint32_t start = 0;
    if (p->length >= 1024 && common < 512 && need <= 4096) {
        p->shield_tokens = p->length < need ? p->length : need;
        transfer t = {s, p->shield, 0, p->shield_bytes, 1};
        sq_am_engine_prefix_global(&t, p->shield_tokens);
        sq_am_engine_prefix_sync_transfer(s);
        s->prefix_info.shielded_tokens = p->shield_tokens;
        return 0;
    }
    int best = -1;
    if (common && p->use_mtp == mtp) {
        if (p->live > 0 && (uint32_t)p->live <= common)
            start = (uint32_t)p->live;
        for (unsigned i = 0; i < 4; i++)
            if (p->checkpoints[i].valid && p->checkpoints[i].position <= common &&
                p->checkpoints[i].position > start) {
                best = (int)i;
                start = p->checkpoints[i].position;
            }
    }
    if (!start)
        sq_prefix_invalidate(s);
    else {
        if (best >= 0) {
            transfer t = {s, p->checkpoints[best].data, 0, p->local_bytes, 0};
            sq_am_engine_prefix_local(&t);
            sq_am_engine_prefix_sync_transfer(s);
            s->prefix_info.checkpoint_restores++;
        }
        s->position = (int32_t)start;
        const sq_weight_backend *b = &s->weights->backend;
        if (s->status == SQ_OK)
            sq_ar_check(s, b->copy(b->context, s->d_pos, &s->position, 4, 0, s->stream),
                        "restore prefix position");
        s->prefix_info.reused_tokens = start;
    }
    for (unsigned i = 0; i < 4; i++)
        if (p->checkpoints[i].position > start)
            p->checkpoints[i].valid = false;
    p->live = -1;
    return start;
}

void sq_prefix_prompt(sq_session *s, const int32_t *tokens, uint32_t n, bool mtp) {
    sq_prefix *p = &s->prefix;
    if (!p->enabled || p->shield_tokens || s->status != SQ_OK)
        return;
    memcpy(p->tokens, tokens, (size_t)n * 4);
    p->length = n;
    p->use_mtp = mtp;
    if (n >= 128)
        sq_prefix_save(s, 2, n);
}

void sq_prefix_feed(sq_session *s, int32_t token) {
    sq_prefix *p = &s->prefix;
    if (p->enabled && !p->shield_tokens && s->status == SQ_OK &&
        p->length < s->config.context_tokens)
        p->tokens[p->length++] = token;
}

void sq_prefix_finish(sq_session *s, bool cancelled) {
    sq_prefix *p = &s->prefix;
    if (!p->enabled)
        return;
    if (cancelled || s->status != SQ_OK) {
        sq_prefix_invalidate(s);
        return;
    }
    if (p->shield_tokens) {
        transfer t = {s, p->shield, 0, p->shield_bytes, 0};
        sq_am_engine_prefix_global(&t, p->shield_tokens);
        sq_am_engine_prefix_sync_transfer(s);
        p->live = -1;
        p->shield_tokens = 0;
    } else {
        p->live = s->position;
        if (p->length >= 128)
            sq_prefix_save(s, 3, p->length);
    }
    if (s->status != SQ_OK)
        sq_prefix_invalidate(s);
}


/* Module: src/engine_prefill.c */
/* SPDX-License-Identifier: Apache-2.0
 * Copyright (c) 2026 tensorfish; Copyright (c) 2026 Artalis
 * Pinned Engine.prefill_chunk_batched with optional DSpark tap commits. */


#define CHECK(call)                                                                                \
    do {                                                                                           \
        sq_ar_check(s, (call), "batched prefill");                                                 \
        if (s->status != SQ_OK)                                                                    \
            return;                                                                                \
    } while (0)

static void sq_am_engine_prefill_gemm(sq_session *s, const CLinearWeight *w, const void *x, float *y, int32_t n) {
    if (s->status == SQ_OK)
        sq_ar_check(s, sq_prefill_gemm_h(s->blas, w, x, y, s->p_w_f16, n, s->stream),
                    "prefill GEMM");
}

static void sq_am_engine_prefill_controller(sq_session *s, const float *x, const float *q, const CControllerWeights *cw,
                       const void *norm, float *out, void *out_h, int32_t n) {
    if (s->status == SQ_OK)
        sq_ar_check(s,
                    sq_prefill_controller_one(s->blas, x, s->p_saved, s->p_prior_last, q, cw, norm,
                                              out, out_h, s->p_ctrl_msg, s->p_ctrl_cat_h,
                                              s->p_ctrl_d, s->p_ctrl_d_h, s->p_ctrl_f, s->p_ctrl_g,
                                              s->p_w_f16, n, s->stream),
                    "prefill controller");
}

void sq_ar_prefill(sq_session *s, const int32_t *tokens, int32_t n) {
    if (s->status != SQ_OK)
        return;
    if (!s->blas)
        CHECK(sq_blas_create(&s->blas, s->stream));
    int32_t pos[256];
    for (int32_t i = 0; i < n / 8; i++)
        pos[i] = s->position + i * 8;
    const sq_weight_backend *backend = &s->weights->backend;
    CHECK(backend->copy(backend->context, s->p_pos_vec, pos, (size_t)(n / 8) * 4, 0, s->stream));
    CHECK(backend->copy(backend->context, s->p_tokens, tokens, (size_t)n * 4, 0, s->stream));
    void *stream = s->stream;
    const sq_ar_model *w = &s->model;
    squid_launch_embed_norm(w->embed, w->embed_norm, s->p_tokens, s->p_hidden, n, stream);
    int32_t blocks = 0;
    bool prior = false, pending = false;
    for (unsigned vi = 0; vi < 48; vi++) {
        sq_visit v = s->schedule[vi];
        unsigned l = v.layer;
        const sq_layer *lw = &w->layers[l];
        bool prelude = false;
        if (v.loop && l == 6) {
            if (v.pass == 0)
                prelude = true;
            else {
                squid_launch_extract_block(s->p_blocks, 4, 2, s->p_saved, n, stream);
                squid_launch_rmsnorm(s->p_hidden, NULL, s->p_prior_last, n, 2304, 2304, 1e-6f,
                                     stream);
                CHECK(backend->copy(backend->context, s->p_hidden, s->p_prelude,
                                    (size_t)n * 2304 * 4, 2, stream));
                blocks = 1;
                prior = true;
            }
        }
        bool use_prior = v.loop && prior, distinct = v.global || use_prior, boundary = l % 6 == 0;
        if (pending) {
            const sq_layer *prev = &w->layers[s->schedule[vi - 1].layer];
            squid_launch_prefill_sconv_post_res(s->p_moe_slot_out, 1, prev->mlp_sconv_w,
                                                s->mlp_ring[vi - 1], s->p_residual, s->p_hidden,
                                                prelude ? s->p_prelude : NULL, NULL, NULL, 0, 0, n,
                                                s->p_pos_vec, NULL, NULL, NULL, stream);
        }
        if (s->use_mtp && (vi == 5 || vi == 23 || vi == 41))
            squid_launch_prefill_copy_taps(s->p_hidden, s->p_taps,
                                           vi == 5    ? 0
                                           : vi == 23 ? 1
                                                      : 2,
                                           n, stream);
        pending = false;
        const void *norm[3] = {NULL, NULL, NULL};
        float *out[3] = {NULL, NULL, NULL};
        void *half[3] = {NULL, NULL, NULL};
        int32_t count = 1;
        if (!distinct) {
            norm[0] = lw->attn_norm;
            out[0] = s->p_attn_in[0];
            half[0] = s->p_attn_in_h[0];
        } else if (v.global && !use_prior) {
            norm[0] = lw->q_in_norm;
            norm[1] = lw->k_in_norm;
            norm[2] = lw->v_in_norm;
            for (unsigned j = 0; j < 3; j++) {
                out[j] = s->p_attn_in[j];
                half[j] = s->p_attn_in_h[j];
            }
            count = 3;
        } else if (v.global) {
            for (unsigned j = 0; j < 3; j++)
                out[j] = s->p_attn_in[j];
            count = 3;
        } else
            out[0] = s->p_mlp_in;
        squid_launch_fused_depth_norm(s->p_hidden, boundary ? s->p_partial : NULL, s->p_blocks,
                                      blocks, l ? w->attn_queries[l - 1] : NULL, norm[0], norm[1],
                                      norm[2], out[0], out[1], out[2], half[0], half[1], half[2],
                                      count, n, stream);
        if (use_prior) {
            unsigned loc = l - 6;
            const float *q[3] = {w->cross_pass_queries + 2 * loc * 2304,
                                 w->cross_pass_kv_queries + 2 * loc * 2304,
                                 w->cross_pass_kv_queries + (2 * loc + 1) * 2304};
            const void *norms[3] = {v.global ? lw->q_in_norm : lw->attn_norm,
                                    v.global ? lw->k_in_norm : lw->attn_norm,
                                    v.global ? lw->v_in_norm : lw->attn_norm};
            for (unsigned j = 0; j < 3; j++)
                sq_am_engine_prefill_controller(s, v.global ? s->p_attn_in[j] : s->p_mlp_in, q[j], &lw->ctrl[j],
                           norms[j], s->p_attn_in[j], s->p_attn_in_h[j], n);
        }
        void *ik = s->p_attn_in_h[distinct ? 1 : 0], *iv = s->p_attn_in_h[distinct ? 2 : 0];
        sq_am_engine_prefill_gemm(s, &lw->w_qrgs, s->p_attn_in_h[0], s->p_qrgs, n);
        sq_am_engine_prefill_gemm(s, &lw->w_k, ik, s->p_k_proj, n);
        sq_am_engine_prefill_gemm(s, &lw->w_v, iv, s->p_v_proj, n);
        if (s->status != SQ_OK)
            return;
        if (v.global) {
            CHECK(sq_prefill_global_sconv_prep_store(
                s->blas, s->p_qrgs, s->p_k_proj, s->p_v_proj, ik, iv, lw->k_sconv_w, lw->v_sconv_w,
                lw->k_sconv_proj, lw->v_sconv_proj, s->k_ring[vi], s->v_ring[vi], lw->q_clip_scale,
                lw->rel_clip_scale, s->k_cache[vi], s->v_cache[vi], s->k_scale[vi], s->v_scale[vi],
                (uint8_t)s->config.kv_format, s->kv_cap[vi], s->p_ctrl_d, s->p_w_f16, n,
                s->p_pos_vec, stream));
            squid_launch_prefill_flash_attn_tc(s->p_qrgs, lw->rel_logits_proj, s->k_cache[vi],
                                               s->v_cache[vi], s->k_scale[vi], s->v_scale[vi],
                                               (uint8_t)s->config.kv_format, s->p_attn_gated_h,
                                               s->kv_cap[vi], 0, n, s->p_pos_vec, stream);
        } else
            for (int32_t off = 0; off < n;) {
                int32_t sub = n - off > 256 ? 256 : n - off;
                float *qrgs = s->p_qrgs + (size_t)off * 6552, *k = s->p_k_proj + (size_t)off * 1024,
                      *val = s->p_v_proj + (size_t)off * 1024;
                const int32_t *p = s->p_pos_vec + off / 8;
                squid_launch_prefill_local_sconv_prep_store(
                    qrgs, k, val, lw->k_sconv_w, lw->v_sconv_w, s->k_ring[vi], s->v_ring[vi],
                    lw->q_clip_scale, lw->rel_clip_scale, s->k_cache[vi], s->v_cache[vi],
                    s->kv_cap[vi], sub, p, stream);
                squid_launch_prefill_flash_attn_tc(
                    qrgs, lw->rel_logits_proj, s->k_cache[vi], s->v_cache[vi], NULL, NULL, 0,
                    (unsigned char *)s->p_attn_gated_h + (size_t)off * 3072 * 2, s->kv_cap[vi],
                    1024, sub, p, stream);
                off += sub;
            }
        sq_am_engine_prefill_gemm(s, &lw->w_o, s->p_attn_gated_h, s->p_o_proj, n);
        if (s->status != SQ_OK)
            return;
        squid_launch_prefill_sconv_post_res(s->p_o_proj, 0, lw->attn_sconv_w, s->attn_ring[vi],
                                            s->p_hidden, s->p_residual, NULL, s->p_blocks,
                                            s->p_partial, blocks, boundary ? 1 : 0, n, s->p_pos_vec,
                                            NULL, NULL, NULL, stream);
        if (boundary)
            blocks++;
        squid_launch_fused_depth_norm(
            s->p_residual, NULL, s->p_blocks, blocks, w->mlp_queries[l],
            use_prior ? NULL : lw->mlp_norm, NULL, NULL, use_prior ? s->p_mlp_in : s->p_mlp_normed,
            NULL, NULL, use_prior ? NULL : s->p_mlp_normed_h, NULL, NULL, 1, n, stream);
        if (use_prior)
            sq_am_engine_prefill_controller(s, s->p_mlp_in, w->cross_pass_queries + (2 * (l - 6) + 1) * 2304,
                       &lw->ctrl[3], lw->mlp_norm, s->p_mlp_normed, s->p_mlp_normed_h, n);
        CLinearWeight router = lw->router_nvfp4;
        if (s->weights->config.mode != 2) {
            router = (CLinearWeight){0, 128, 2304, lw->router_w, NULL, NULL, 1};
        }
        sq_am_engine_prefill_gemm(s, &router, s->p_mlp_normed_h, s->p_router_logits, n);
        if (s->status != SQ_OK)
            return;
        squid_launch_prefill_route_and_sort(s->p_router_logits, lw->router_bias, s->p_route_ids,
                                            s->p_route_w, s->p_exp_offsets, s->p_sorted_tok,
                                            s->p_sorted_slot, s->p_sorted_w, n, stream);
        squid_launch_prefill_moe_gate_up_h(&lw->w13, s->p_mlp_normed_h, s->p_exp_offsets,
                                           s->p_sorted_tok, s->p_sorted_slot, s->p_moe_act_h, n,
                                           stream);
        squid_launch_prefill_moe_down_h(&lw->w2, s->p_moe_act_h, s->p_exp_offsets, s->p_sorted_tok,
                                        s->p_sorted_slot, s->p_sorted_w, s->p_moe_slot_out, n,
                                        stream);
        if (vi == 17 || vi == 29)
            squid_launch_prefill_sconv_post_res(
                s->p_moe_slot_out, 1, lw->mlp_sconv_w, s->mlp_ring[vi], s->p_residual, s->p_hidden,
                NULL, NULL, NULL, 0, 0, n, s->p_pos_vec, NULL, NULL, NULL, stream);
        else
            pending = true;
        CHECK(sq_cuda_launch_status());
    }
    squid_launch_prefill_sconv_post_res(s->p_moe_slot_out, 1,
                                        w->layers[s->schedule[47].layer].mlp_sconv_w,
                                        s->mlp_ring[47], s->p_residual, s->p_hidden, NULL, NULL,
                                        NULL, 0, 0, n, s->p_pos_vec, NULL, NULL, NULL, stream);
    squid_launch_fused_depth_norm(s->p_hidden, NULL, s->p_blocks, blocks, w->output_query,
                                  w->final_norm, NULL, NULL, s->p_mlp_normed, NULL, NULL, NULL,
                                  NULL, NULL, 1, n, stream);
    if (s->use_mtp) {
        squid_launch_prefill_copy_taps(s->p_mlp_normed, s->p_taps, 3, n, stream);
        for (int32_t i = 0; i < n / 8; i++)
            sq_spec_commit(s, s->p_taps + (size_t)i * 4 * 8 * 2304, 8, s->p_pos_vec + i);
    }
    CHECK(sq_cuda_launch_status());
    CHECK(backend->sync(backend->context, stream));
    s->position += n;
}

#undef CHECK

