/* SPDX-License-Identifier: Apache-2.0; Copyright (c) 2026 Artalis */
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <time.h>

/* Header is maximally aligned and private to our allocator, never an ABI record. */
typedef union {
    max_align_t alignment;

    struct {
        size_t bytes;
    } value;
} si_allocation;

static void *sq_am_infer_budget_allocate(void *context, size_t bytes) {
    si_budget *b = context;
    size_t total;
    if (!sq_size_add(sizeof(si_allocation), bytes, &total))
        return NULL;
    uint_fast64_t old = atomic_load_explicit(&b->live, memory_order_relaxed);
    do {
        if (old > b->limit || total > b->limit - old)
            return NULL;
    } while (!atomic_compare_exchange_weak_explicit(&b->live, &old, old + total,
                                                    memory_order_relaxed, memory_order_relaxed));
    si_allocation *p = b->upstream.allocate(b->upstream.context, total);
    if (!p) {
        atomic_fetch_sub_explicit(&b->live, total, memory_order_relaxed);
        return NULL;
    }
    p->value.bytes = total;
    return p + 1;
}

static void sq_am_infer_budget_release(void *context, void *ptr) {
    if (!ptr)
        return;
    si_budget *b = context;
    si_allocation *p = (si_allocation *)ptr - 1;
    size_t total = p->value.bytes;
    b->upstream.release(b->upstream.context, p);
    atomic_fetch_sub_explicit(&b->live, total, memory_order_relaxed);
}

void si_budget_init(si_budget *b, const sq_options *upstream, uint64_t limit, sq_options *out) {
    b->upstream = *upstream;
    b->limit = limit;
    atomic_init(&b->live, 0);
    *out = (sq_options)SQ_OPTIONS_INIT;
    out->context = b;
    out->allocate = sq_am_infer_budget_allocate;
    out->release = sq_am_infer_budget_release;
}

void *si_alloc(const sq_options *a, size_t n) {
    return a->allocate(a->context, n);
}

void si_free(const sq_options *a, void *p) {
    if (p)
        a->release(a->context, p);
}

bool si_lock(atomic_flag *f) {
    return !atomic_flag_test_and_set_explicit(f, memory_order_acquire);
}

void si_unlock(atomic_flag *f) {
    atomic_flag_clear_explicit(f, memory_order_release);
}

sq_status si_input(const void *record, size_t known) {
    if (!record)
        return SQ_INVALID_ARGUMENT;
    sq_infer_in h;
    memcpy(&h, record, sizeof h);
    if (h.struct_size < known || h.struct_size > SQ_INFER_RECORD_MAX_BYTES || h.flags)
        return SQ_INVALID_ARGUMENT;
    const unsigned char *p = record;
    for (size_t i = known; i < h.struct_size; i++)
        if (p[i])
            return SQ_UNSUPPORTED;
    return SQ_OK;
}

sq_status si_output(void *out, const void *value, size_t known) {
    if (!out)
        return SQ_INVALID_ARGUMENT;
    sq_infer_out *h = out;
    uint32_t capacity = h->struct_size;
    if (capacity < known || capacity > SQ_INFER_RECORD_MAX_BYTES)
        return SQ_INVALID_ARGUMENT;
    memcpy(out, value, known);
    h->struct_size = capacity;
    h->written_size = (uint32_t)known;
    return SQ_OK;
}

sq_status si_error(sq_infer_error_v1 *out, sq_status status, uint32_t stage, const char *text) {
    if (out) {
        sq_infer_error_v1 e = {0};
        e.status = status;
        e.stage = status ? stage : SQ_STAGE_NONE;
        if (status && text) {
            (void)snprintf(e.message, sizeof e.message, "%s", text);
            e.message_bytes = (uint32_t)strlen(e.message);
        }
        (void)si_output(out, &e, sizeof e);
    }
    return status;
}

sq_status si_native_error(sq_infer_error_v1 *e, sq_status rc, uint32_t stage) {
    /* Backend diagnostics contain operation names/codes, never input contents. */
    sq_status status = si_error(e, rc, stage, rc ? sq_status_string(rc) : "");
    if (e && e->hdr.struct_size >= sizeof *e && e->hdr.struct_size <= SQ_INFER_RECORD_MAX_BYTES &&
        rc && stage == SQ_STAGE_CLOSE)
        e->flags |= SQ_INFER_ERR_CLEANUP_PENDING;
    return status;
}

bool si_span(sq_infer_bytes s, size_t max) {
    return s.bytes <= max && (!s.bytes || s.data);
}

bool si_equal(sq_infer_bytes s, const char *text) {
    return si_span(s, 4096) && s.bytes == strlen(text) &&
           (!s.bytes || !memcmp(s.data, text, (size_t)s.bytes));
}

sq_infer_bytes si_text(const char *s) {
    return (sq_infer_bytes){s, strlen(s)};
}

sq_status si_no_extensions(sq_infer_array a) {
    return a.reserved             ? SQ_INVALID_ARGUMENT
           : a.count              ? SQ_UNSUPPORTED
           : (a.data || a.stride) ? SQ_INVALID_ARGUMENT
                                  : SQ_OK;
}

uint64_t si_now(void) {
    struct timespec t;
    if (clock_gettime(CLOCK_MONOTONIC, &t))
        return 0;
    return (uint64_t)t.tv_sec * UINT64_C(1000000000) + (uint64_t)t.tv_nsec;
}

sq_status si_defaults(uint32_t kind, void *out, sq_infer_error_v1 *e) {
    size_t size = kind == SQ_DEFAULT_MODEL     ? sizeof(sq_infer_model_config_v1)
                  : kind == SQ_DEFAULT_SESSION ? sizeof(sq_infer_session_config_v1)
                  : kind == SQ_DEFAULT_REQUEST ? sizeof(sq_infer_request_config_v1)
                                               : 0;
    if (!size || !out || ((sq_infer_in *)out)->struct_size < size ||
        ((sq_infer_in *)out)->struct_size > SQ_INFER_RECORD_MAX_BYTES)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE, "invalid defaults record");
    uint32_t capacity = ((sq_infer_in *)out)->struct_size;
    memset(out, 0, size);
    ((sq_infer_in *)out)->struct_size = capacity;
    if (kind == SQ_DEFAULT_MODEL) {
        sq_infer_model_config_v1 *c = out;
        c->max_owned_host_bytes = c->max_owned_device_bytes = UINT64_MAX;
        c->device_id = si_text("0");
        c->weight_profile = si_text("nvfp4-ar");
    } else if (kind == SQ_DEFAULT_SESSION) {
        sq_infer_session_config_v1 *c = out;
        c->max_owned_host_bytes = c->max_owned_device_bytes = UINT64_MAX;
        c->context_tokens = 8192;
        c->execution_profile = si_text("fp8-graph");
    } else {
        sq_infer_request_config_v1 *c = out;
        c->max_output_tokens = 256;
        c->top_p = 0.95f;
        c->output_kind = SQ_OUTPUT_TEXT;
        c->max_event_bytes = 4096;
    }
    return si_error(e, SQ_OK, 0, NULL);
}

sq_status si_backend_info(sq_infer_backend_info_v1 *out, sq_infer_error_v1 *e) {
    sq_infer_backend_info_v1 v = {0};
    v.backend_id = si_text("artalis.squid");
    v.engine_revision =
        si_text("upstream:d10c0abb2c8990be81c08ba84c66a8333a691b33;infer:1.0-experimental");
    v.compiled_features = SI_FEATURES;
    v.pointer_bits = sizeof(void *) * 8;
    v.limit_scope = SQ_LIMIT_PROVIDER_PROCESS;
    v.max_prepared_sessions = v.max_active_runs = 1;
    return si_error(e, si_output(out, &v, sizeof v), SQ_STAGE_VALIDATE, "invalid backend output");
}

static sq_status sq_am_infer_query_extension(uint64_t id, uint32_t version, const void **out,
                                 sq_infer_error_v1 *e) {
    (void)id;
    (void)version;
    if (out)
        *out = NULL;
    return si_error(e, out ? SQ_UNSUPPORTED : SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE,
                    "no extension function table");
}

static const sq_infer_api_v1 sq_am_infer_api = {
    sizeof(sq_infer_api_v1), SQ_INFER_ABI_MAJOR, SQ_INFER_ABI_MINOR, 0,
    si_backend_info,         si_defaults,        si_model_create,    si_model_plan,
    si_model_load,           si_model_info,      si_model_close,     si_session_create,
    si_session_plan,         si_session_prepare, si_session_info,    si_session_clear,
    si_session_close,        si_request_create,  si_request_run,     si_request_cancel,
    si_request_progress,     si_request_result,  si_request_close,   sq_am_infer_query_extension};

sq_status sq_infer_get_api(uint32_t major, uint32_t minor, const void **out) {
    if (!out)
        return SQ_INVALID_ARGUMENT;
    *out = NULL;
    if (sizeof(void *) != 8 || major != SQ_INFER_ABI_MAJOR || minor > SQ_INFER_ABI_MINOR)
        return SQ_INFER_ABI_MISMATCH;
    *out = &sq_am_infer_api;
    return SQ_OK;
}


/* Module: src/infer_model.c */
/* SPDX-License-Identifier: Apache-2.0; Copyright (c) 2026 Artalis */

#include <stdio.h>

static uint64_t sq_am_infer_model_features(const sq_infer_model *m) {
    return m->weights_config.with_mtp ? SI_FEATURES : SI_FEATURES & ~SQ_INFER_CAP_SPECULATION;
}

static sq_status sq_am_infer_model_source_paths(const sq_infer_source_v1 *s, char paths[3][4096]) {
    sq_status rc = si_input(s, sizeof *s);
    if (rc)
        return rc;
    if (!si_equal(s->format_id, "inkling-safetensors") || !si_span(s->directory, 4000) ||
        !s->directory.bytes || memchr(s->directory.data, 0, (size_t)s->directory.bytes))
        return SQ_INVALID_ARGUMENT;
    const char *names[] = {"tokenizer.json", "model-00001-of-00001.safetensors", "mtp.safetensors"};
    for (size_t i = 0; i < 3; i++) {
        int n = snprintf(paths[i], 4096, "%.*s/%s", (int)s->directory.bytes,
                         (const char *)s->directory.data, names[i]);
        if (n < 0 || n >= 4096)
            return SQ_LIMIT;
    }
    return SQ_OK;
}

sq_status si_model_create(const sq_infer_model_config_v1 *c, sq_infer_model **out,
                          sq_infer_error_v1 *e) {
    if (out)
        *out = NULL;
    sq_status rc = si_input(c, sizeof *c);
    if (rc || !out)
        return si_error(e, rc ? rc : SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE,
                        "invalid model configuration");
    rc = si_no_extensions(c->extensions);
    if (rc || (c->required_features & ~SI_FEATURES))
        return si_error(e, rc ? rc : SQ_UNSUPPORTED, SQ_STAGE_VALIDATE,
                        "unsupported model features");
    sq_options a = SQ_OPTIONS_INIT;
    a.context = c->allocator.context;
    a.allocate = c->allocator.allocate;
    a.release = c->allocator.release;
    sq_options resolved;
    rc = sq_options_resolve(&a, &resolved);
    a = resolved;
    if (rc)
        return si_native_error(e, rc, SQ_STAGE_VALIDATE);
    if (c->max_owned_host_bytes < sizeof(sq_infer_model))
        return si_error(e, SQ_LIMIT, SQ_STAGE_VALIDATE, "model host budget too small");
    sq_weight_config wc = SQ_WEIGHT_CONFIG_INIT;
    wc.with_mtp = 0;
    const char *profiles[] = {"exact-ar",  "fp8-ar",  "nvfp4-ar",
                              "exact-mtp", "fp8-mtp", "nvfp4-mtp"};
    const char *profile = NULL;
    for (uint32_t i = 0; i < 6; i++)
        if (si_equal(c->weight_profile, profiles[i])) {
            wc.mode = i % 3;
            wc.with_mtp = i / 3;
            profile = profiles[i];
        }
    if (!profile || !si_span(c->device_id, 10) || !c->device_id.bytes)
        return si_error(e, SQ_UNSUPPORTED, SQ_STAGE_VALIDATE,
                        "unknown weight profile or device identifier");
    uint32_t device = 0;
    for (size_t i = 0; i < c->device_id.bytes; i++) {
        unsigned char ch = ((const unsigned char *)c->device_id.data)[i];
        if (ch < '0' || ch > '9' || device > 214748364u || (device == 214748364u && ch > '7'))
            return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE,
                            "device must be a nonnegative CUDA ordinal");
        device = device * 10 + (uint32_t)(ch - '0');
    }
    wc.device = (int32_t)device;
    if (!wc.with_mtp && (c->required_features & SQ_INFER_CAP_SPECULATION))
        return si_error(e, SQ_UNSUPPORTED, SQ_STAGE_VALIDATE,
                        "speculation requires an MTP profile");
    sq_infer_model *m = si_alloc(&a, sizeof *m);
    if (!m)
        return si_error(e, SQ_OUT_OF_MEMORY, SQ_STAGE_VALIDATE, "allocate model");
    memset(m, 0, sizeof *m);
    si_budget_init(&m->budget, &a, c->max_owned_host_bytes - sizeof *m, &m->allocator);
    atomic_flag_clear(&m->busy);
    (void)snprintf(m->device_id, sizeof m->device_id, "%u", device);
    m->weights_config = wc;
    m->profile = profile;
    m->required = c->required_features;
    m->device_budget = c->max_owned_device_bytes;
    *out = m;
    return si_error(e, SQ_OK, 0, NULL);
}

sq_status si_model_plan(sq_infer_model *m, const sq_infer_source_v1 *s,
                        sq_infer_memory_plan_v1 *out, sq_infer_error_v1 *e) {
    if (!m)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE, "missing model");
    if (!si_lock(&m->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_VALIDATE, "model busy");
    char paths[3][4096];
    sq_status rc = sq_am_infer_model_source_paths(s, paths);
    sq_weight_plan plan = {0};
    if (!rc)
        rc = sq_weights_plan(&m->weights_config, &m->allocator, &plan);
    if (!rc) {
        sq_infer_memory_plan_v1 v = {0};
        v.owned_host_bytes = sizeof *m + atomic_load(&m->budget.live);
        v.owned_device_bytes = plan.arena_bytes;
        v.peak_owned_device_bytes = plan.peak_device_bytes;
        /* Tokenizer/maps and vendor allocations are not known before loading. */
        v.unknown_fields = UINT64_C(3) | SI_UNKNOWN_VENDOR;
        rc = si_output(out, &v, sizeof v);
    }
    si_unlock(&m->busy);
    return si_native_error(e, rc, SQ_STAGE_VALIDATE);
}

sq_status si_model_load(sq_infer_model *m, const sq_infer_source_v1 *s, sq_infer_error_v1 *e) {
    if (!m)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_LOAD, "missing model");
    if (!si_lock(&m->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_LOAD, "model busy");
    sq_status rc = m->state == SQ_HANDLE_CREATED ? SQ_OK : SQ_INFER_INVALID_STATE;
    char paths[3][4096];
    if (!rc)
        rc = sq_am_infer_model_source_paths(s, paths);
    sq_weight_plan plan;
    if (!rc)
        rc = sq_weights_plan(&m->weights_config, &m->allocator, &plan);
    if (!rc && plan.peak_device_bytes > m->device_budget)
        rc = SQ_LIMIT;
    if (rc) {
        si_unlock(&m->busy);
        return si_native_error(e, rc, SQ_STAGE_LOAD);
    }
    m->state = SQ_HANDLE_PREPARING;
    rc = sq_tokenizer_open(paths[0], &m->allocator, &m->tokenizer);
    if (!rc)
        rc = sq_inkling_checkpoint_open(paths[1], m->weights_config.with_mtp ? paths[2] : NULL,
                                        &m->allocator, &m->checkpoint);
    if (!rc)
        rc = sq_gpu_weights_create(&m->weights_config, &m->allocator, &m->weights);
    if (!rc)
        rc = sq_gpu_weights_load(m->weights, m->checkpoint);
    if (!rc) {
        sq_inkling_checkpoint_close(m->checkpoint);
        m->checkpoint = NULL;
    }
    /* On failure retain mapped input until native cleanup has succeeded. Even
     * a failed stream synchronization must not shorten borrowed DMA lifetime. */
    m->state = rc ? SQ_HANDLE_FAILED : SQ_HANDLE_READY;
    si_unlock(&m->busy);
    return si_native_error(e, rc, SQ_STAGE_LOAD);
}

sq_status si_model_info(sq_infer_model *m, sq_infer_model_info_v1 *out, sq_infer_error_v1 *e) {
    if (!m)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE, "missing model");
    if (!si_lock(&m->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_VALIDATE, "model busy");
    sq_infer_model_info_v1 v = {0};
    v.state = m->state;
    v.max_prepared_sessions = 1;
    v.supported_features = sq_am_infer_model_features(m);
    v.enabled_features = m->state == SQ_HANDLE_READY ? sq_am_infer_model_features(m) & ~SQ_INFER_CAP_PREFIX_CACHE : 0;
    v.max_context_tokens = 1048576;
    v.max_messages = 1024;
    v.max_input_bytes = SI_MAX_INPUT;
    v.max_stops = 8;
    v.max_stop_bytes = 64;
    v.max_event_bytes = 65536;
    v.model_id = si_text("inkling-2-mini");
    v.resolved_weight_profile = si_text(m->profile);
    v.resolved_device_id = si_text(m->device_id);
    v.tokenizer_id = si_text("inkling-bpe");
    v.template_id = si_text("inkling-text-v1");
    /* No invented artifact hash: fingerprint_verified remains false. */
    sq_status rc = si_output(out, &v, sizeof v);
    si_unlock(&m->busy);
    return si_native_error(e, rc, SQ_STAGE_VALIDATE);
}

sq_status si_model_close(sq_infer_model **ptr, sq_infer_error_v1 *e) {
    if (!ptr)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_CLOSE, "missing handle pointer");
    sq_infer_model *m = *ptr;
    if (!m)
        return si_error(e, SQ_OK, 0, NULL);
    if (!si_lock(&m->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_CLOSE, "model busy");
    if (m->children) {
        si_unlock(&m->busy);
        return si_error(e, SQ_BUSY, SQ_STAGE_CLOSE, "model has sessions");
    }
    m->state = SQ_HANDLE_CLOSING;
    sq_status rc = sq_gpu_weights_destroy(&m->weights);
    if (rc) {
        si_unlock(&m->busy);
        return si_native_error(e, rc, SQ_STAGE_CLOSE);
    }
    sq_inkling_checkpoint_close(m->checkpoint);
    sq_tokenizer_close(m->tokenizer);
    sq_options a = m->budget.upstream;
    si_free(&a, m);
    *ptr = NULL;
    return si_error(e, SQ_OK, 0, NULL);
}


/* Module: src/infer_session.c */
/* SPDX-License-Identifier: Apache-2.0; Copyright (c) 2026 Artalis */

static sq_status sq_am_infer_session_plan_locked(sq_infer_session *s, sq_infer_memory_plan_v1 *v) {
    uint64_t bytes = 0;
    sq_status rc = sq_session_owned_plan(s->model->weights, &s->config, &s->allocator, &bytes);
    if (rc)
        return rc;
    memset(v, 0, sizeof *v);
    v->owned_host_bytes = sizeof *s + atomic_load(&s->budget.live);
    v->owned_device_bytes = v->peak_owned_device_bytes = bytes;
    v->unknown_fields = UINT64_C(1) | SI_UNKNOWN_VENDOR;
    return SQ_OK;
}

sq_status si_session_create(sq_infer_model *m, const sq_infer_session_config_v1 *c,
                            sq_infer_session **out, sq_infer_error_v1 *e) {
    if (out)
        *out = NULL;
    sq_status rc = si_input(c, sizeof *c);
    if (rc || !out || !m)
        return si_error(e, rc ? rc : SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE,
                        "invalid session arguments");
    rc = si_no_extensions(c->extensions);
    if (rc)
        return si_native_error(e, rc, SQ_STAGE_VALIDATE);
    sq_session_config sc = SQ_SESSION_CONFIG_INIT;
    if (c->context_tokens < 64 || c->context_tokens > 1048576 ||
        c->max_owned_host_bytes < sizeof(sq_infer_session))
        return si_error(e, SQ_LIMIT, SQ_STAGE_VALIDATE, "session context or host budget invalid");
    sc.context_tokens = (uint32_t)c->context_tokens;
    const char *profiles[] = {"bf16-eager", "fp8-eager", "q4-eager",
                              "bf16-graph", "fp8-graph", "q4-graph"};
    const char *profile = NULL;
    for (uint32_t i = 0; i < 6; i++)
        if (si_equal(c->execution_profile, profiles[i])) {
            sc.kv_format = i % 3;
            sc.use_graphs = i / 3;
            profile = profiles[i];
        }
    if (!profile)
        return si_error(e, SQ_UNSUPPORTED, SQ_STAGE_VALIDATE, "unknown execution profile");
    if (!si_lock(&m->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_VALIDATE, "model busy");
    if (m->state != SQ_HANDLE_READY || m->children == UINT32_MAX) {
        si_unlock(&m->busy);
        return si_error(e, SQ_INFER_NOT_READY, SQ_STAGE_VALIDATE, "model not ready");
    }
    sq_infer_session *s = si_alloc(&m->allocator, sizeof *s);
    if (!s) {
        si_unlock(&m->busy);
        return si_error(e, SQ_OUT_OF_MEMORY, SQ_STAGE_VALIDATE, "allocate session");
    }
    memset(s, 0, sizeof *s);
    s->model = m;
    s->config = sc;
    s->profile = profile;
    s->device_budget = c->max_owned_device_bytes;
    si_budget_init(&s->budget, &m->allocator, c->max_owned_host_bytes - sizeof *s, &s->allocator);
    atomic_flag_clear(&s->busy);
    m->children++;
    si_unlock(&m->busy);
    *out = s;
    return si_error(e, SQ_OK, 0, NULL);
}

sq_status si_session_plan(sq_infer_session *s, sq_infer_memory_plan_v1 *out, sq_infer_error_v1 *e) {
    if (!s)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE, "missing session");
    if (!si_lock(&s->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_VALIDATE, "session busy");
    sq_infer_memory_plan_v1 v;
    sq_status rc = sq_am_infer_session_plan_locked(s, &v);
    if (!rc)
        rc = si_output(out, &v, sizeof v);
    si_unlock(&s->busy);
    return si_native_error(e, rc, SQ_STAGE_VALIDATE);
}

sq_status si_session_prepare(sq_infer_session *s, sq_infer_error_v1 *e) {
    if (!s)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_PREPARE, "missing session");
    if (!si_lock(&s->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_PREPARE, "session busy");
    sq_status rc = s->state == SQ_HANDLE_CREATED ? SQ_OK : SQ_INFER_INVALID_STATE;
    sq_infer_memory_plan_v1 v;
    if (!rc)
        rc = sq_am_infer_session_plan_locked(s, &v);
    if (!rc && v.peak_owned_device_bytes > s->device_budget)
        rc = SQ_LIMIT;
    if (!rc) {
        s->state = SQ_HANDLE_PREPARING;
        rc = sq_session_create(s->model->weights, &s->config, &s->allocator, &s->native);
        s->state = rc ? ((rc == SQ_BUSY && !s->native) ? SQ_HANDLE_CREATED : SQ_HANDLE_FAILED)
                      : SQ_HANDLE_READY;
    }
    si_unlock(&s->busy);
    return si_native_error(e, rc, SQ_STAGE_PREPARE);
}

sq_status si_session_info(sq_infer_session *s, sq_infer_session_info_v1 *out,
                          sq_infer_error_v1 *e) {
    if (!s)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE, "missing session");
    if (!si_lock(&s->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_VALIDATE, "session busy");
    sq_infer_session_info_v1 v = {0};
    v.state = s->state;
    v.max_active_runs = 1;
    v.context_tokens = s->config.context_tokens;
    v.enabled_features = s->state == SQ_HANDLE_READY ? SI_FEATURES & ~SQ_INFER_CAP_PREFIX_CACHE : 0;
    if (!s->model->weights_config.with_mtp)
        v.enabled_features &= ~SQ_INFER_CAP_SPECULATION;
    if (s->cache_scope_bytes)
        v.enabled_features |= SQ_INFER_CAP_PREFIX_CACHE;
    v.resolved_execution_profile = si_text(s->profile);
    sq_status rc = si_output(out, &v, sizeof v);
    si_unlock(&s->busy);
    return si_native_error(e, rc, SQ_STAGE_VALIDATE);
}

sq_status si_session_clear(sq_infer_session *s, sq_infer_error_v1 *e) {
    if (!s)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE, "missing session");
    if (!si_lock(&s->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_VALIDATE, "session busy");
    sq_status rc =
        s->state == SQ_HANDLE_READY ? sq_session_prefix_cache(s->native, 0) : SQ_INFER_NOT_READY;
    if (!rc)
        s->cache_scope_bytes = 0;
    si_unlock(&s->busy);
    return si_native_error(e, rc, SQ_STAGE_VALIDATE);
}

sq_status si_session_close(sq_infer_session **ptr, sq_infer_error_v1 *e) {
    if (!ptr)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_CLOSE, "missing handle pointer");
    sq_infer_session *s = *ptr;
    if (!s)
        return si_error(e, SQ_OK, 0, NULL);
    if (!si_lock(&s->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_CLOSE, "session busy");
    if (s->children) {
        si_unlock(&s->busy);
        return si_error(e, SQ_BUSY, SQ_STAGE_CLOSE, "session has requests");
    }
    sq_infer_model *m = s->model;
    if (!si_lock(&m->busy)) {
        si_unlock(&s->busy);
        return si_error(e, SQ_BUSY, SQ_STAGE_CLOSE, "model busy");
    }
    s->state = SQ_HANDLE_CLOSING;
    sq_status rc = sq_session_destroy(&s->native);
    if (rc) {
        si_unlock(&m->busy);
        si_unlock(&s->busy);
        return si_native_error(e, rc, SQ_STAGE_CLOSE);
    }
    m->children--;
    si_free(&m->allocator, s);
    *ptr = NULL;
    si_unlock(&m->busy);
    return si_error(e, SQ_OK, 0, NULL);
}


/* Module: src/infer_request.c */
/* SPDX-License-Identifier: Apache-2.0; Copyright (c) 2026 Artalis */

#include <math.h>

static bool sq_am_infer_request_cancelled(void *context) {
    sq_infer_request *r = context;
    return (atomic_load_explicit(&r->control, memory_order_acquire) & SI_CANCEL) != 0;
}

static sq_status sq_am_infer_request_array_valid(sq_infer_array a, size_t element, size_t maximum) {
    if (a.reserved || a.count > maximum || (a.count && (!a.data || a.stride < element)) ||
        (a.count && a.count > SIZE_MAX / a.stride))
        return SQ_INVALID_ARGUMENT;
    if (!a.count && (a.data || a.stride))
        return SQ_INVALID_ARGUMENT;
    return SQ_OK;
}

static sq_status sq_am_infer_request_request_options(sq_infer_request *r, const sq_infer_request_config_v1 *c,
                                 sq_chat_options *chat) {
    sq_status rc = si_input(c, sizeof *c);
    if (rc)
        return rc;
    uint64_t supported = SI_FEATURES;
    if (!r->session->model->weights_config.with_mtp)
        supported &= ~SQ_INFER_CAP_SPECULATION;
    if (c->required_features & ~supported)
        return SQ_UNSUPPORTED;
    if (!c->max_output_tokens || c->max_output_tokens > r->session->config.context_tokens ||
        !isfinite(c->temperature) || c->temperature < 0 || !isfinite(c->top_p) || c->top_p <= 0 ||
        c->top_p > 1 || c->top_k < 0 || c->top_k > 200058 || c->output_kind < SQ_OUTPUT_TEXT ||
        c->output_kind > SQ_OUTPUT_DISCARD || c->max_event_bytes < 4 ||
        c->max_event_bytes > 65536 || c->reserved ||
        (c->output_flags & ~SQ_INFER_OUTPUT_REASONING) || c->history_policy > 1 ||
        !si_span(c->cache_scope, sizeof r->scope))
        return SQ_INVALID_ARGUMENT;
    rc = sq_am_infer_request_array_valid(c->extensions, sizeof(sq_infer_extension_v1), 16);
    if (rc)
        return rc;
    if (c->extensions.count > 1)
        return SQ_UNSUPPORTED;
    r->decode = (sq_decode_options)SQ_DECODE_OPTIONS_INIT;
    r->decode.temperature = c->temperature;
    r->decode.top_p = c->top_p;
    r->decode.top_k = c->top_k;
    r->decode.seed = c->seed;
    *chat = (sq_chat_options)SQ_CHAT_OPTIONS_INIT;
    chat->keep_history_thinking = c->history_policy;
    for (size_t i = 0; i < c->extensions.count; i++) {
        const unsigned char *p =
            (const unsigned char *)c->extensions.data + i * c->extensions.stride;
        sq_infer_extension_v1 ext;
        memcpy(&ext, p, sizeof ext);
        /* Read headers/tails as bytes, including padded array elements. */
        if (ext.hdr.struct_size > c->extensions.stride)
            return SQ_INVALID_ARGUMENT;
        rc = si_input(p, sizeof ext);
        if (rc)
            return rc;
        if (ext.id != SQ_INFER_EXT_SQUID_REQUEST || ext.version != 1 ||
            ext.payload_bytes < sizeof(sq_infer_squid_request_v1) ||
            ext.payload_bytes > SQ_INFER_RECORD_MAX_BYTES || !ext.payload)
            return SQ_UNSUPPORTED;
        sq_infer_squid_request_v1 v;
        memcpy(&v, ext.payload, sizeof v);
        if (v.hdr.struct_size > ext.payload_bytes)
            return SQ_INVALID_ARGUMENT;
        rc = si_input(ext.payload, sizeof v);
        if (rc)
            return rc;
        if (v.draft_tokens > 7 || v.adaptive > 1 || v.prompt_lookup > 1 ||
            v.thinking_effort > SQ_THINK_MAX || v.enable_thinking > 1 ||
            !isfinite(v.spec_threshold) ||
            (v.adaptive && (v.spec_threshold <= 0 || v.spec_threshold > 1)))
            return SQ_INVALID_ARGUMENT;
        if ((v.draft_tokens && !r->session->model->weights_config.with_mtp) ||
            (v.adaptive && (v.draft_tokens != 7 || !r->session->config.use_graphs)) ||
            (v.prompt_lookup && !v.adaptive))
            return SQ_UNSUPPORTED;
        r->decode.draft_tokens = v.draft_tokens;
        r->decode.adaptive = v.adaptive;
        r->decode.prompt_lookup = v.prompt_lookup;
        if (v.adaptive)
            r->decode.spec_threshold = v.spec_threshold;
        chat->effort = v.thinking_effort;
        chat->enable_thinking = v.enable_thinking;
    }
    r->config = *c;
    /* Borrowed configuration pointers never survive creation. */
    r->config.extensions = (sq_infer_array){0};
    r->config.stops = (sq_infer_array){0};
    r->config.cache_scope = (sq_infer_bytes){0};
    r->scope_bytes = (size_t)c->cache_scope.bytes;
    if (r->scope_bytes)
        memcpy(r->scope, c->cache_scope.data, r->scope_bytes);
    return SQ_OK;
}

static sq_status sq_am_infer_request_encode(sq_infer_request *r, const sq_infer_input_v1 *in,
                        const sq_chat_options *chat) {
    sq_status rc = si_input(in, sizeof *in);
    if (rc)
        return rc;
    if (in->reserved || !si_span(in->text, SI_MAX_INPUT))
        return SQ_INVALID_ARGUMENT;
    if (in->kind != SQ_INPUT_CHAT &&
        (chat->effort || chat->enable_thinking || chat->keep_history_thinking))
        return SQ_UNSUPPORTED;
    size_t capacity = r->session->config.context_tokens - (size_t)r->config.max_output_tokens;
    if (!capacity)
        return SQ_LIMIT;
    size_t bytes;
    if (!sq_size_mul(capacity, sizeof(int32_t), &bytes))
        return SQ_LIMIT;
    r->tokens = si_alloc(&r->allocator, bytes);
    if (!r->tokens)
        return SQ_OUT_OF_MEMORY;
    if (in->kind == SQ_INPUT_TOKENS) {
        if (in->text.data || in->text.bytes || si_no_extensions(in->messages) || !in->tokens ||
            !in->token_count || in->token_count > capacity ||
            r->config.output_kind == SQ_OUTPUT_TEXT)
            return SQ_INVALID_ARGUMENT;
        for (size_t i = 0; i < in->token_count; i++) {
            if (in->tokens[i] < 0 || in->tokens[i] >= 200058)
                return SQ_INVALID_ARGUMENT;
            r->tokens[i] = in->tokens[i];
        }
        r->token_count = (size_t)in->token_count;
        return SQ_OK;
    }
    if (in->tokens || in->token_count)
        return SQ_INVALID_ARGUMENT;
    sq_tokenizer_scratch *scratch = NULL;
    rc = sq_tokenizer_scratch_create(&r->allocator, &scratch);
    if (rc)
        return rc;
    if (in->kind == SQ_INPUT_RAW_TEXT) {
        if (si_no_extensions(in->messages))
            rc = SQ_INVALID_ARGUMENT;
        else
            rc = sq_tokenizer_encode(r->session->model->tokenizer, in->text.data,
                                     (size_t)in->text.bytes, 0, scratch, r->tokens, capacity,
                                     &r->token_count);
    } else if (in->kind == SQ_INPUT_CHAT) {
        rc = sq_am_infer_request_array_valid(in->messages, sizeof(sq_infer_message_v1), 1024);
        if (in->text.data || in->text.bytes || !in->messages.count)
            rc = SQ_INVALID_ARGUMENT;
        sq_chat_message *messages = NULL;
        if (!rc) {
            messages = si_alloc(&r->allocator, (size_t)in->messages.count * sizeof *messages);
            if (!messages)
                rc = SQ_OUT_OF_MEMORY;
        }
        uint64_t total = 0;
        for (size_t i = 0; !rc && i < in->messages.count; i++) {
            sq_infer_message_v1 m;
            const unsigned char *p =
                (const unsigned char *)in->messages.data + i * in->messages.stride;
            memcpy(&m, p, sizeof m);
            if (m.hdr.struct_size > in->messages.stride) {
                rc = SQ_INVALID_ARGUMENT;
                break;
            }
            rc = si_input(p, sizeof m);
            if (rc)
                break;
            if (m.content_present > 1 || m.role < SQ_ROLE_SYSTEM || m.role > SQ_ROLE_ASSISTANT ||
                !si_span(m.content, SI_MAX_INPUT) || !si_span(m.reasoning, SI_MAX_INPUT) ||
                !si_span(m.name, 128) ||
                (!m.content_present && (m.content.data || m.content.bytes))) {
                rc = SQ_INVALID_ARGUMENT;
                break;
            }
            total += m.content.bytes + m.reasoning.bytes + m.name.bytes;
            if (total > SI_MAX_INPUT) {
                rc = SQ_LIMIT;
                break;
            }
            messages[i] =
                (sq_chat_message){m.role - 1,
                                  0,
                                  m.content_present ? (m.content.data ? m.content.data : "") : NULL,
                                  (size_t)m.content.bytes,
                                  m.reasoning.data,
                                  (size_t)m.reasoning.bytes,
                                  m.name.data,
                                  (size_t)m.name.bytes};
        }
        if (!rc)
            rc = sq_chat_encode(r->session->model->tokenizer, messages, (size_t)in->messages.count,
                                chat, scratch, r->tokens, capacity, &r->token_count,
                                &r->decode.system_prefix_tokens);
        si_free(&r->allocator, messages);
    } else
        rc = SQ_UNSUPPORTED;
    sq_tokenizer_scratch_destroy(scratch);
    return !rc && !r->token_count ? SQ_INVALID_ARGUMENT : rc;
}

static uint32_t sq_am_infer_request_emit_event(sq_infer_request *r, uint32_t kind, const void *text, size_t bytes,
                           const int32_t *tokens, size_t count) {
    if (sq_am_infer_request_cancelled(r))
        return SQ_CALLBACK_CANCEL;
    sq_infer_event_v1 v = {0};
    v.hdr.struct_size = v.hdr.written_size = sizeof v;
    v.kind = kind;
    v.sequence = r->sequence++;
    v.generated_tokens_so_far = atomic_load_explicit(&r->generated, memory_order_relaxed);
    v.text = (sq_infer_bytes){text, bytes};
    v.tokens = tokens;
    v.token_count = count;
    uint32_t action = r->emit(r->context, &v);
    if (kind == SQ_EVENT_CONTENT)
        r->result.content_bytes += bytes;
    if (kind == SQ_EVENT_REASONING)
        r->result.reasoning_bytes += bytes;
    uint64_t now = si_now();
    if (now && r->started) {
        if (kind == SQ_EVENT_CONTENT && !(r->result.timing_valid & SQ_INFER_TIME_FIRST_CONTENT)) {
            r->result.first_content_ns = now - r->started;
            r->result.timing_valid |= SQ_INFER_TIME_FIRST_CONTENT;
        }
        if (kind == SQ_EVENT_REASONING &&
            !(r->result.timing_valid & SQ_INFER_TIME_FIRST_REASONING)) {
            r->result.first_reasoning_ns = now - r->started;
            r->result.timing_valid |= SQ_INFER_TIME_FIRST_REASONING;
        }
    }
    if (action > SQ_CALLBACK_CANCEL) {
        r->callback_status = SQ_INVALID_ARGUMENT;
        return SQ_CALLBACK_STOP;
    }
    if (action == SQ_CALLBACK_CANCEL) {
        uint32_t disposition;
        (void)si_request_cancel(r, &disposition, NULL);
    }
    if (action)
        r->callback_action = action;
    return action;
}

static int sq_am_infer_request_text_event(void *context, uint32_t channel, const char *p, size_t n) {
    sq_infer_request *r = context;
    if (sq_am_infer_request_cancelled(r))
        return 0;
    if (channel == SQ_STREAM_REASONING && !(r->config.output_flags & SQ_INFER_OUTPUT_REASONING))
        return 1;
    while (n) {
        size_t take = n > r->config.max_event_bytes ? r->config.max_event_bytes : n;
        if (take < n)
            while (take && (((unsigned char)p[take] & 0xc0) == 0x80))
                take--;
        if (!take) {
            r->callback_status = SQ_FORMAT;
            return 0;
        }
        if (sq_am_infer_request_emit_event(r, channel == SQ_STREAM_REASONING ? SQ_EVENT_REASONING : SQ_EVENT_CONTENT, p,
                       take, NULL, 0))
            return 0;
        p += take;
        n -= take;
    }
    return 1;
}

static int sq_am_infer_request_token_event(void *context, int32_t token) {
    sq_infer_request *r = context;
    atomic_fetch_add_explicit(&r->generated, 1, memory_order_relaxed);
    if (sq_am_infer_request_cancelled(r))
        return 0;
    if (r->config.output_kind == SQ_OUTPUT_RAW_TOKENS)
        return sq_am_infer_request_emit_event(r, SQ_EVENT_TOKENS, NULL, 0, &token, 1) == SQ_CALLBACK_CONTINUE;
    if (r->config.output_kind == SQ_OUTPUT_DISCARD)
        return 1;
    sq_status rc = sq_stream_push_token(r->stream, token);
    if (rc) {
        r->callback_status = rc;
        return 0;
    }
    sq_stream_info info = SQ_STREAM_INFO_INIT;
    rc = sq_stream_get_info(r->stream, &info);
    if (rc) {
        r->callback_status = rc;
        return 0;
    }
    return info.finish_reason == SQ_STREAM_RUNNING;
}

static void sq_am_infer_request_release_request(sq_infer_request *r) {
    (void)sq_stream_destroy(&r->stream);
    si_free(&r->allocator, r->tokens);
    sq_options a = r->allocator;
    si_free(&a, r);
}

sq_status si_request_create(sq_infer_session *s, const sq_infer_input_v1 *input,
                            const sq_infer_request_config_v1 *config, sq_infer_request **out,
                            sq_infer_error_v1 *e) {
    if (out)
        *out = NULL;
    if (!s || !out)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE, "invalid request arguments");
    if (!si_lock(&s->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_VALIDATE, "session busy");
    if (s->state != SQ_HANDLE_READY || s->children == UINT32_MAX) {
        si_unlock(&s->busy);
        return si_error(e, SQ_INFER_NOT_READY, SQ_STAGE_VALIDATE, "session not ready");
    }
    uint64_t start = si_now();
    sq_infer_request *r = si_alloc(&s->allocator, sizeof *r);
    if (!r) {
        si_unlock(&s->busy);
        return si_error(e, SQ_OUT_OF_MEMORY, SQ_STAGE_VALIDATE, "allocate request");
    }
    memset(r, 0, sizeof *r);
    r->session = s;
    r->allocator = s->allocator;
    atomic_init(&r->control, 0);
    atomic_init(&r->phase, SQ_REQUEST_PREPARED);
    atomic_init(&r->running, false);
    atomic_init(&r->generated, 0);
    atomic_init(&r->processed, 0);
    SQ_INFER_INIT(r->terminal_error);
    sq_chat_options chat;
    sq_status rc = sq_am_infer_request_request_options(r, config, &chat);
    if (!rc)
        rc = sq_am_infer_request_encode(r, input, &chat);
    sq_text_span stops[8];
    if (!rc)
        rc = sq_am_infer_request_array_valid(config->stops, sizeof(sq_infer_bytes), 8);
    if (!rc && config->output_kind != SQ_OUTPUT_TEXT && config->stops.count)
        rc = SQ_UNSUPPORTED;
    for (size_t i = 0; !rc && i < config->stops.count; i++) {
        sq_infer_bytes span;
        memcpy(&span, (const unsigned char *)config->stops.data + i * config->stops.stride,
               sizeof span);
        if (!si_span(span, 64) || !span.bytes) {
            rc = SQ_INVALID_ARGUMENT;
            break;
        }
        stops[i] = (sq_text_span){span.data, (size_t)span.bytes};
    }
    if (!rc && config->output_kind == SQ_OUTPUT_TEXT) {
        sq_stream_options options = SQ_STREAM_OPTIONS_INIT;
        options.parse_chat = input->kind == SQ_INPUT_CHAT;
        options.stops = stops;
        options.stop_count = (size_t)config->stops.count;
        rc = sq_stream_create(s->model->tokenizer, &options, &r->allocator, sq_am_infer_request_text_event, r,
                              &r->stream);
    }
    if (rc) {
        sq_am_infer_request_release_request(r);
        si_unlock(&s->busy);
        return si_native_error(e, rc, SQ_STAGE_VALIDATE);
    }
    s->children++;
    uint64_t now = si_now();
    if (start && now) {
        r->result.prepare_ns = now - start;
        r->result.timing_valid |= SQ_INFER_TIME_PREPARE;
    }
    r->result.input_tokens = r->token_count;
    r->result.resolved_execution_profile = si_text(s->profile);
    *out = r;
    si_unlock(&s->busy);
    return si_error(e, SQ_OK, 0, NULL);
}

static sq_status sq_am_infer_request_scope_begin(sq_infer_request *r) {
    sq_infer_session *s = r->session;
    bool same = r->scope_bytes && r->scope_bytes == s->cache_scope_bytes &&
                !memcmp(r->scope, s->cache_scope, r->scope_bytes);
    if (!same) {
        sq_status rc = sq_session_prefix_cache(s->native, 0);
        s->cache_scope_bytes = 0;
        if (rc)
            return rc;
    }
    if (r->scope_bytes && !same) {
        sq_status rc = sq_session_prefix_cache(s->native, 1);
        if (rc)
            return rc;
        memcpy(s->cache_scope, r->scope, r->scope_bytes);
        s->cache_scope_bytes = r->scope_bytes;
    }
    return SQ_OK;
}

sq_status si_request_run(sq_infer_request *r, sq_infer_emit_fn emit, void *context,
                         sq_infer_error_v1 *e) {
    if (!r || (!emit && r->config.output_kind != SQ_OUTPUT_DISCARD))
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE,
                        "missing request or output callback");
    sq_infer_session *s = r->session;
    if (!si_lock(&s->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_VALIDATE, "session already executing");
    if (atomic_load_explicit(&r->phase, memory_order_acquire) != SQ_REQUEST_PREPARED) {
        si_unlock(&s->busy);
        return si_error(e, SQ_INFER_INVALID_STATE, SQ_STAGE_VALIDATE, "request is one-shot");
    }
    if (s->state != SQ_HANDLE_READY) {
        si_unlock(&s->busy);
        return si_error(e, SQ_INFER_NOT_READY, SQ_STAGE_VALIDATE, "session not ready");
    }
    atomic_store_explicit(&r->running, true, memory_order_release);
    atomic_store_explicit(&r->phase, SQ_REQUEST_RUNNING, memory_order_release);
    r->emit = emit;
    r->context = context;
    r->started = si_now();
    sq_status rc = SQ_OK;
    bool native_called = false;
    sq_decode_stats stats = {0};
    if (!sq_am_infer_request_cancelled(r))
        rc = sq_am_infer_request_scope_begin(r);
    if (!rc && !sq_am_infer_request_cancelled(r)) {
        native_called = true;
        sq_run_control control = {sq_am_infer_request_cancelled, r};
        rc = sq_session_generate_controlled(s->native, r->tokens, r->token_count,
                                            (size_t)r->config.max_output_tokens, &r->decode,
                                            sq_am_infer_request_token_event, r, &stats, &control);
        if (rc && rc != SQ_CANCELLED)
            s->state = SQ_HANDLE_POISONED;
        if (!rc || rc == SQ_CANCELLED) {
            sq_prefix_info p = SQ_PREFIX_INFO_INIT;
            if (sq_session_prefix_info(s->native, &p) == SQ_OK)
                r->result.prefix_reused_tokens = p.reused_tokens;
        }
    }
    if (native_called)
        atomic_store_explicit(&r->processed, r->token_count, memory_order_relaxed);
    if (!rc && r->callback_status)
        rc = r->callback_status;
    if (!rc && !sq_am_infer_request_cancelled(r) && r->stream) {
        rc = sq_stream_finish(r->stream, SQ_STREAM_LENGTH);
        if (!rc && r->callback_status)
            rc = r->callback_status;
    }
    /* One atomic seal is the cancellation/completion linearization point.
     * Session lease stays held through all cancellation/error invalidation. */
    unsigned sealed = atomic_fetch_or_explicit(&r->control, SI_SEALED, memory_order_acq_rel);
    bool was_cancelled = (sealed & SI_CANCEL) != 0 || rc == SQ_CANCELLED;
    sq_status cleanup = SQ_OK;
    if ((was_cancelled || rc) && s->state == SQ_HANDLE_READY) {
        cleanup = sq_session_reset(s->native);
        if (cleanup)
            s->state = SQ_HANDLE_POISONED;
        s->cache_scope_bytes = 0;
    }
    sq_status primary = rc;
    if (cleanup && (!rc || rc == SQ_CANCELLED))
        rc = cleanup;
    if (!rc && was_cancelled)
        rc = SQ_CANCELLED;
    r->result.status = rc;
    r->result.cancel_requested = (sealed & SI_CANCEL) != 0;
    r->result.generated_tokens = atomic_load_explicit(&r->generated, memory_order_relaxed);
    r->result.finish_reason = rc == SQ_CANCELLED ? SQ_FINISH_CANCELLED_V1
                              : rc               ? SQ_FINISH_ERROR_V1
                              : stats.generation.finish_reason == SQ_FINISH_EOS ? SQ_FINISH_EOS_V1
                              : r->callback_action == SQ_CALLBACK_STOP ? SQ_FINISH_CALLBACK_V1
                                                                       : SQ_FINISH_OUTPUT_LIMIT_V1;
    if (r->stream) {
        sq_stream_info info = SQ_STREAM_INFO_INIT;
        if (sq_stream_get_info(r->stream, &info) == SQ_OK) {
            r->result.utf8_replacements = info.utf8_replacements;
            if (!rc && info.finish_reason == SQ_STREAM_STOP)
                r->result.finish_reason = SQ_FINISH_STOP_STRING_V1;
            if (!rc && info.finish_reason == SQ_STREAM_EOS)
                r->result.finish_reason = SQ_FINISH_EOS_V1;
        }
    }
    uint64_t now = si_now();
    if (now && r->started) {
        r->result.run_ns = now - r->started;
        r->result.timing_valid |= SQ_INFER_TIME_RUN;
    }
    (void)si_native_error(&r->terminal_error, rc, SQ_STAGE_DECODE);
    if (s->state == SQ_HANDLE_POISONED)
        r->terminal_error.flags |= SQ_INFER_ERR_SESSION_POISONED;
    if (r->sequence)
        r->terminal_error.flags |= SQ_INFER_ERR_OUTPUT_STARTED;
    if (cleanup) {
        r->terminal_error.cleanup_status = cleanup;
        r->terminal_error.flags |= SQ_INFER_ERR_CLEANUP_PENDING;
        if (primary && primary != SQ_CANCELLED)
            r->terminal_error.status = primary;
    }
    r->emit = NULL;
    r->context = NULL;
    atomic_store_explicit(&r->phase,
                          rc == SQ_CANCELLED ? SQ_REQUEST_CANCELLED
                          : rc               ? SQ_REQUEST_FAILED
                                             : SQ_REQUEST_COMPLETED,
                          memory_order_release);
    if (e)
        (void)si_output(e, &r->terminal_error, sizeof r->terminal_error);
    /* No access to r after releasing session: close holds the same lease. */
    atomic_store_explicit(&r->running, false, memory_order_release);
    si_unlock(&s->busy);
    return rc;
}

sq_status si_request_cancel(sq_infer_request *r, uint32_t *disposition, sq_infer_error_v1 *e) {
    if (disposition)
        *disposition = 0;
    if (!r || !disposition)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE,
                        "missing cancellation arguments");
    unsigned old = atomic_load_explicit(&r->control, memory_order_acquire);
    for (;;) {
        if (old & SI_SEALED) {
            *disposition = SQ_CANCEL_TOO_LATE;
            break;
        }
        if (old & SI_CANCEL) {
            *disposition = SQ_CANCEL_ALREADY_REQUESTED;
            break;
        }
        if (atomic_compare_exchange_weak_explicit(&r->control, &old, old | SI_CANCEL,
                                                  memory_order_acq_rel, memory_order_acquire)) {
            *disposition = SQ_CANCEL_ACCEPTED;
            break;
        }
    }
    return si_error(e, SQ_OK, 0, NULL);
}

sq_status si_request_progress(const sq_infer_request *r, sq_infer_progress_v1 *out,
                              sq_infer_error_v1 *e) {
    if (!r)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE, "missing request");
    sq_infer_progress_v1 v = {0};
    v.state = atomic_load_explicit(&r->phase, memory_order_acquire);
    v.cancel_requested = (atomic_load_explicit(&r->control, memory_order_acquire) & SI_CANCEL) != 0;
    v.generated_tokens = atomic_load_explicit(&r->generated, memory_order_relaxed);
    v.prompt_tokens_processed = atomic_load_explicit(&r->processed, memory_order_relaxed);
    return si_native_error(e, si_output(out, &v, sizeof v), SQ_STAGE_VALIDATE);
}

sq_status si_request_result(const sq_infer_request *r, sq_infer_result_v1 *out,
                            sq_infer_error_v1 *e) {
    if (!r)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_VALIDATE, "missing request");
    unsigned phase = atomic_load_explicit(&r->phase, memory_order_acquire);
    if (phase == SQ_REQUEST_PREPARED || phase == SQ_REQUEST_RUNNING)
        return si_error(e, SQ_INFER_NOT_READY, SQ_STAGE_VALIDATE, "request has no terminal result");
    sq_status rc = si_output(out, &r->result, sizeof r->result);
    return si_native_error(e, rc, SQ_STAGE_VALIDATE);
}

sq_status si_request_close(sq_infer_request **ptr, sq_infer_error_v1 *e) {
    if (!ptr)
        return si_error(e, SQ_INVALID_ARGUMENT, SQ_STAGE_CLOSE, "missing handle pointer");
    sq_infer_request *r = *ptr;
    if (!r)
        return si_error(e, SQ_OK, 0, NULL);
    sq_infer_session *s = r->session;
    if (!si_lock(&s->busy))
        return si_error(e, SQ_BUSY, SQ_STAGE_CLOSE, "session busy");
    if (atomic_load_explicit(&r->running, memory_order_acquire)) {
        si_unlock(&s->busy);
        return si_error(e, SQ_BUSY, SQ_STAGE_CLOSE, "request running");
    }
    s->children--;
    sq_am_infer_request_release_request(r);
    *ptr = NULL;
    si_unlock(&s->busy);
    return si_error(e, SQ_OK, 0, NULL);
}

#endif /* SQ_ENABLE_CUDA */
